const AU124={"name": "10. 124-Day Pre-Departure Recap - AUTOMATED 124-days before departure date", "status": "inactive", "ev": "trip_start_date", "dir": "before", "days": 124, "time": "08:00", "tz": "America/New_York", "acts": [{"t": "email", "subject": "Your 124-Day Pre-Departure Recap — Viking (Itinerary Name)", "rec": "primary_traveler", "ind": false, "body": "Dear (First Name),\nAs promised, here is everything we confirmed, in one place, so you have a single document to refer back to.\n• Voyage: (Itinerary Name) aboard Viking (Ship), (Departure Date) – (Return Date)\n• Stateroom: (Category Name), Cabin (Number) · Confirmation (Number)\n• Flights: (Airline, flight numbers, routing, times) (if you have purchased Viking Air+)\n• Pre-cruise hotel: (Hotel Name), (Nights)\n• Transfers: (Arrangement)\n• Embarkation: (Port), (Date), check-in from (Time)\n• Dietary and special requests on file with Viking: (Details)\n• Travel insurance: (Provider), policy (Number)\n• Passports verified valid through: (Date)\nIf you have any questions at this point, please feel free to call me anytime to discuss your trip. You know your own plans better than any documents do, and small corrections are effortless at this stage.\nStill to come from me: a check-in call at about 30 days, your Luxury Travel Institute pre-departure packet at two weeks, a final confirmation call at ten days, and a note with practical tips the week you leave. This is the point where it starts to feel real.\nSincerely,\n", "att": [], "prev": false}, {"t": "task", "title": "New Task", "asg": "", "due": 7, "dt": "after_task_creation", "urg": false, "desc": "• -attach the guest statement and guest information form to AI TERN\n• **PROMPT: fill out the email with the details based on the attached guest statement and guest information form - (copy and paste everything below to AI TERN).\n• \nSubject: Your 124-Day Pre-Departure Recap — Viking [Itinerary Name]\n\nDear [First Name], \n\n\nAs promised, here is everything we confirmed, in one place, so you have a single document to refer back to.\n\n• Voyage: [Itinerary Name] aboard Viking [Ship], [Departure Date] – [Return Date]\n• Stateroom: [Category Name], Cabin [Number] · Confirmation [Number]\n• Flights: [Airline, flight numbers, routing, times] (if you have purchased Viking Air+)\n• Pre-cruise hotel: [Hotel Name],  [Nights]\n• Transfers: [Arrangement]\n• Embarkation: [Port], [Date], check-in from [Time]\n• Dietary and special requests on file with Viking: [Details]\n• Travel insurance: [Provider], policy [Number]\n• Passports verified valid through: [Date]\n\nIf you have any questions at this point, please feel free to call me anytime to discuss your trip. You know your own plans better than any documents do, and small corrections are effortless at this stage.\n\nStill to come from me: a check-in call at about 30 days, your Luxury Travel Institute pre-departure packet at two weeks, a final confirmation call at ten days, and a note with practical tips the week you leave. This is the point where it\nstarts to feel real.\n\nSincerely,", "notif": false}]};
