function aumk(r){const nm=r[0];let t;const mm=nm.match(/^(\d+)\./);
 if(mm&&mm[1]!='10'&&AU18[mm[1]])t=JSON.parse(JSON.stringify(AU18[mm[1]]));
 else if(nm.indexOf('124-Day Pre-Departure Recap')>=0)t=JSON.parse(JSON.stringify(AU124));
 else if(nm=='1. BOOKING CONFIRMATION'){t={ev:'automation_added',dir:'',days:'',time:'',tz:'America/New_York',status:'inactive',acts:[Object.assign(auEmail(),{subject:BKB.subject,body:BKB.body}),Object.assign(auTask(),{due:7})]}}
 else{const ev=(AUEV.find(x=>x[1].toLowerCase()==String(r[3]).toLowerCase()||(r[3]=='Trip Start Date'&&x[0]=='trip_start_date'))||[''])[0],m=nm.match(/(\d+)\s*-?\s*days?/i);
  t={ev,dir:/after/i.test(nm)?'after':'before',days:m?+m[1]:'',time:'08:00',tz:'America/New_York',status:String(r[5]).toLowerCase(),part:1,acts:[]};
  if(/send email/i.test(r[4]))t.acts.push(auEmail());if(/create \d+ task/i.test(r[4]))t.acts.push(auTask())}
 t.name=nm;t.folder=S.afp[0]||'My templates';t.row=r;if(!t.status)t.status='inactive';return t}
function aud(i){const r=aRows()[i],k=(S.afp[0]||'')+'|'+r[0];if(!S.aut[k])S.aut[k]=aumk(r);S.auk=k;S.menu=null;S.tab['aue']=null;go('autoed')}
const aut=()=>S.aut[S.auk];
function auS(k,v){aut()[k]=v;aufl()}
function auA(i,k,v){aut().acts[i][k]=v;aufl()}
function aufl(){const e=document.getElementById('aus');if(e)e.textContent='Saved (demo: kept in this preview only)'}
function auD(){return S.aut[S.auk]}
function auAdd(t){S.menu=null;aut().acts.push(t=='email'?auEmail():auTask());draw()}
function auDel(i){dlg('Delete action','<p>Delete this action from the automation?</p>','Delete',()=>{aut().acts.splice(i,1);cl();draw()})}
function auAtt(i,inp){const a=aut().acts[i];for(const f of inp.files)a.att.push(f.name);draw()}
function auRm(i,j){aut().acts[i].att.splice(j,1);draw()}
function auForm(i){const a=aut().acts[i];a.body+=(a.body&&!/\n$/.test(a.body)?'\n':'')+'[Form link]';draw()}
function auApply(close){const t=aut(),r=t.row,ne=t.acts.filter(a=>a.t=='email').length,nt=t.acts.filter(a=>a.t=='task').length,n=[];
 if(ne)n.push('Send email');if(nt)n.push('Create '+nt+' task'+(nt>1?'s':''));
 const old=S.auk;r[0]=t.name;if(t.ev&&t.evch)r[3]=aulab(AUEV,t.ev);r[4]=n.join(' · ')||'–';r[5]=t.status=='active'?'Active':'Inactive';r[6]='Oct 31, 2026';
 const nk=(S.afp[0]||'')+'|'+t.name;if(nk!=old){delete S.aut[old];S.aut[nk]=t;S.auk=nk}
 toast('Saved in this browser');if(close)go('libau');else draw()}
function auDup(){S.menu=null;const t=aut(),f=S.afp[0],L=f?AUD[f]:null;if(!L){auRootDup(t);return}
 const i=L.indexOf(t.row),r=t.row.slice();r[0]=t.name+' (copy)';r[5]='Inactive';r[6]='Oct 31, 2026';L.splice(i+1,0,r);const c=JSON.parse(JSON.stringify(Object.assign({},t,{row:null})));c.row=r;c.name=r[0];c.status='inactive';S.aut[f+'|'+r[0]]=c;toast('Duplicated "'+t.name+'"');draw()}
function auDelT(){S.menu=null;const t=aut(),f=S.afp[0],L=f?AUD[f]:null;if(!L){auRootDel(t);return}
 dlg('Delete automation','<p>Delete <b>'+esc(t.name)+'</b>? This cannot be undone.</p>','Delete',()=>{const i=L.indexOf(t.row);if(i>=0)L.splice(i,1);delete S.aut[S.auk];cl();go('libau')})}
const auPv=b=>esc(b).replace(/(\([^()\n]{1,60}\)|\[[^\[\]\n]{0,60}\])/g,'<mark style="background:var(--gt);color:var(--gdk);border-radius:3px;padding:0 2px">$1</mark>');
const auSw=(on,fn,id)=>`<button type="button" role="switch" aria-checked="${on?'true':'false'}" aria-labelledby="${id}" onclick="${fn}" style="width:36px;height:20px;border-radius:99px;border:0;padding:2px;cursor:pointer;background:${on?'var(--ok)':'var(--ln)'};display:inline-flex;justify-content:${on?'flex-end':'flex-start'};flex:none"><span style="width:16px;height:16px;border-radius:50%;background:#fff;display:block;box-shadow:0 1px 2px #0003"></span></button>`;
const auAct=(ttl,sub,i,body)=>`<section class="cd"><header><div><h2>${ttl}</h2><div class="mu" style="padding:0;font-size:12px">${sub}</div></div><button class="ib" aria-label="Delete action" title="Delete action" onclick="auDel(${i})">${ic('trash',15)}</button></header><div class="bd">${body}</div></section>`;
Pg.autoed=()=>{const t=aut();if(!t)return emp('bolt','Template not found','Open an automation from the library.','<button class="btn" onclick="go(\'libau\')">Back to automation templates</button>');
 const dated=AUTM.indexOf(t.ev)>=0||(t.ev&&t.dir&&t.days!==''&&t.part!==0&&t.ev!='automation_added'&&AUTM.indexOf(t.ev)>=0),show=AUTM.indexOf(t.ev)>=0||(t.days!==''&&t.ev!='automation_added'&&t.dir);
 const bc=`<div class="mu" style="margin-bottom:10px;padding-left:0"><a class="lk" onclick="S.afp=[];go('libau')">My templates</a>${t.folder!='My templates'?` › <a class="lk" onclick="go('libau')">${esc(t.folder)}</a>`:''} › ${esc(t.name)}</div>`;
 const acts=t.acts.map((a,i)=>{
  if(a.t=='email'){const pv=a.prev;return auAct('Send Email','This email will be sent when this automation runs.',i,
   `<div class="row" style="margin-bottom:10px"><label class="btn o" style="margin:0;cursor:pointer;color:var(--ink);display:inline-flex;gap:6px;align-items:center" title="Add Attachment">${ic('clip',14)} Add Attachment<input type="file" multiple style="display:none;width:auto" onchange="auAtt(${i},this)"></label><button class="btn o" onclick="auForm(${i})">${ic('file',14)} Insert Form</button>${a.att.map((n,j)=>`<span class="chip">${esc(n)}<button aria-label="Remove attachment" onclick="auRm(${i},${j})">×</button></span>`).join('')}</div>`+
   auf('Subject Line',`<input style="padding-left:9px" value="${esc(a.subject)}" oninput="auA(${i},'subject',this.value)" placeholder="Enter subject">`)+
   auf('Recipient',`<select onchange="auA(${i},'rec',this.value)">${auopt(AURC,a.rec,1)}</select>`)+
   `<label class="ts" style="border:0;align-items:center;margin:0 0 10px;color:var(--ink);font-size:13px"><input type="checkbox" style="width:auto;padding:0" ${a.ind?'checked':''} onchange="auA(${i},'ind',this.checked)"><span>Send separate emails to each recipient</span></label>`+
   `<div class="tabs"><button class="${pv?'':'on'}" onclick="auA(${i},'prev',false);draw()">Email Content</button><button class="${pv?'on':''}" onclick="auA(${i},'prev',true);draw()">Preview</button></div>`+
   (pv?`<div style="min-height:200px;white-space:pre-wrap;border:1px solid var(--ln);border-radius:6px;padding:12px"><b>Subject:</b> ${auPv(a.subject)}<hr style="border:0;border-top:1px solid var(--ln);margin:10px 0">${auPv(a.body)}</div>`:`<textarea rows="16" oninput="auA(${i},'body',this.value)" aria-label="Email content">${esc(a.body)}</textarea>`))}
  if(a.t=='task')return auAct('Create Task','This task will be created when this automation runs.',i,
   auf('Task Name',`<input style="padding-left:9px" value="${esc(a.title)}" oninput="auA(${i},'title',this.value)">`)+
   auf('Assignee',`<input style="padding-left:9px" placeholder="Search" value="${esc(a.asg)}" oninput="auA(${i},'asg',this.value)">`)+
   auf('Due Date',`<div class="row"><input type="number" min="0" style="width:80px;padding-left:9px" placeholder="##" aria-label="Number of days" value="${a.due}" oninput="auA(${i},'due',this.value)"><span class="mu" style="padding:0">days</span><select style="width:200px" aria-label="Timing" onchange="auA(${i},'dt',this.value)">${auopt(AUDT,a.dt,1)}</select></div>`)+
   `<label class="ts" style="border:0;align-items:center;margin:0 0 10px;color:var(--ink);font-size:13px"><input type="checkbox" style="width:auto;padding:0" ${a.urg?'checked':''} onchange="auA(${i},'urg',this.checked)"><span>Urgent</span></label>`+
   auf('Description <span style="font-weight:400">(Optional)</span>',`<textarea rows="16" oninput="auA(${i},'desc',this.value)">${esc(a.desc)}</textarea>`)+
   `<div class="row"><span id="aun${i}">Email Notification</span>${auSw(a.notif,`auA(${i},'notif',!aut().acts[${i}].notif);draw()`,'aun'+i)}</div>`);return''}).join('');
 return hd(`<input aria-label="Automation title" style="padding-left:9px;font-size:20px;font-weight:600;min-width:min(520px,80vw)" value="${esc(t.name)}" placeholder="Enter automation title" oninput="auS('name',this.value)">`,
   `<span class="mu" id="aus" style="font-size:12px"></span><button class="btn o" onclick="${T('share')}">Share</button><button class="btn o" onclick="auApply(false)">Apply Updates</button><button class="btn" onclick="auApply(true)">Save &amp; Close</button><span class="rel"><button class="ib" aria-label="Open automation template more actions menu" onclick="mn('au')">···</button>${S.menu=='au'?`<div class="dd"><a onclick="auDup()">Duplicate</a><a onclick="auDelT()" style="color:var(--er)">Delete</a></div>`:''}</span>`)+bc+
 (t.part?`<p class="mu" style="padding-left:0;font-size:12px">Only the summary row was supplied for this automation, so its email text and task description are blank.</p>`:'')+
 `<section class="cd"><div class="bd"><div class="row"><span id="aust">Set automation to active when applied</span>${auSw(t.status=='active',`auS('status',aut().status=='active'?'inactive':'active');draw()`,'aust')}</div></div></section>`+
 `<section class="cd"><header><div><h2>Trigger</h2><div class="mu" style="padding:0;font-size:12px">Pick an event that will cause this automation to run.</div></div></header><div class="bd">`+
 auf('Event',`<select onchange="auS('ev',this.value);aut().evch=1;draw()">${auopt(AUEV,t.ev,1)}</select>`)+
 (AUTM.indexOf(t.ev)>=0?auf('Timing',`<select onchange="auS('dir',this.value)">${auopt(AUDIR,t.dir,1)}</select>`)+
 auf('Details',`<div class="row"><input type="number" min="0" style="width:80px;padding-left:9px" placeholder="##" aria-label="Days" value="${t.days}" oninput="auS('days',this.value)"><span class="mu" style="padding:0">days ${t.dir=='after'?'after':'before'} at</span><input type="time" style="width:120px;padding-left:9px" aria-label="Time of day" value="${t.time}" onchange="auS('time',this.value)"><select style="width:min(320px,100%)" aria-label="Timezone" onchange="auS('tz',this.value)"><option value="">- Timezone</option>${auopt(AUTZ,t.tz)}</select></div>`):(t.ev?`<p class="mu" style="padding:0;margin:0">Runs as soon as this event happens.</p>`:''))+
 `</div></section>`+
 `<h2 style="font-size:15px;margin:18px 0 2px">Actions</h2><p class="mu" style="padding:0;margin:0 0 10px">Add any tasks to automatically create, or an email to automatically send, when this automation runs.</p>`+acts+
 `<div class="rel" style="margin:6px 0 20px"><button class="btn o" onclick="mn('aua')">+ Add an action ${ic('chev',12)}</button>${S.menu=='aua'?`<div class="dd" style="left:0;right:auto;top:38px"><div class="mu" style="font-size:11px">Run AI Agent</div><a onclick="${T('aiagent')}">New Agent</a><a onclick="${T('aiagent')}">From Template</a><div class="mu" style="font-size:11px">Create Task</div><a onclick="auAdd('task')">New Task</a><a onclick="${T('tasktpl')}">From Template</a><div class="mu" style="font-size:11px">Send Email</div><a onclick="auAdd('email')">New Email</a><div class="mu" style="font-size:11px">Trip</div><a onclick="${T('tripstatus')}">Update Trip</a></div>`:''}</div>`};

