function bflt(){const f=S.bf,ag=[...new Set(S.bk.map(b=>b[9]))],sp=[...new Set(S.bk.map(b=>b[2]))];dlg('Filters',`<p><a class="lk" onclick="S.bf={st:[],ag:'',sup:'',cl:'',cn:'',from:'',to:''};cl();draw()">Reset</a></p><label>Status</label>${['Upcoming','Overdue','Partial','Received','Canceled'].map(x=>`<label class="ck" style="margin:0"><input type="checkbox" class="bs" value="${x}" ${f.st.includes(x)?'checked':''}><span>${x}</span></label>`).join('')}<label>Agent</label><select id="f1"><option value="">Any</option>${ag.map(x=>`<option ${f.ag==x?'selected':''}>${esc(x)}</option>`).join('')}</select><label>Supplier</label><select id="f2"><option value="">Any</option>${sp.map(x=>`<option ${f.sup==x?'selected':''}>${esc(x)}</option>`).join('')}</select><label>Client</label><input id="f3" value="${esc(f.cl)}"><label>Booking name</label><input id="f4" placeholder="Not filtered in this preview"><label>Confirmation #</label><input id="f5" value="${esc(f.cn)}"><label>Start date between</label><div class="row"><input id="f6" type="date" value="${f.from}"><input id="f7" type="date" value="${f.to}"></div><label>End date between</label><div class="row"><input type="date" disabled><input type="date" disabled></div><label>Expected commission date between</label><div class="row"><input type="date" disabled><input type="date" disabled></div><label>Booking date between</label><div class="row"><input type="date" disabled><input type="date" disabled></div><label class="ck"><input type="checkbox" disabled><span>Include not commissionable bookings</span></label>`,'Confirm',()=>{S.bf={st:[...document.querySelectorAll('.bs')].filter(x=>x.checked).map(x=>x.value),ag:$('#f1').value,sup:$('#f2').value,cl:$('#f3').value.trim(),cn:$('#f5').value.trim(),from:$('#f6').value,to:$('#f7').value};cl();draw()})}
