function simp(){supImportCsv()}
function smg(){S.menu=null;draw();const o=S.sup.map((x,i)=>`<option value="${i}">${esc(x[0])} (${x[2]})</option>`).join('');dlg('Merge suppliers',`<label>Keep this supplier</label><select id="a1">${o}</select><label>Merge into it and archive this one</label><select id="a2">${o}</select>`,'Merge (demo)',()=>{const a=+$('#a1').value,b=+$('#a2').value;if(a==b){$('#er').textContent='Choose two different suppliers.';return}S.sup[b][5]=0;if(S.sup[b][1])S.sup[a][1]=1;cl();toast('Merged in this preview only');draw()})}
function newG(){dlg('New goal',`<label>Goal name</label><input id="a1" placeholder="e.g. 2027 sales"><label>Measure</label><select id="a2"><option>Sales volume</option><option>Commission received</option></select><label>Applies to</label><select id="a3"><option>Agency</option><option>Each advisor</option></select><label>Period</label><select id="a4"><option>Year</option><option>Quarter</option><option>Month</option></select><label>Target ($)</label><input id="a5" type="number" min="1" placeholder="100000">`,'Create goal',()=>{const n=$('#a1').value.trim(),t=parseFloat($('#a5').value);if(!n||!(t>0)){$('#er').textContent='Enter a goal name and a target above zero.';return}S.goals.push({n,m:$('#a2').value,a:$('#a3').value,p:$('#a4').value,t});cl();toast('Goal created (preview only)');draw()})}
function tfl(){const f=S.trf,ow=[...new Set(['Maya Reyes'].concat(S.sh.map(t=>t.ow)))];dlg('Filters',`<p><a class="lk" onclick="S.trf={from:'',to:'',ow:'',ty:['Regular Trip','Group Trip','Sub-Trip'],cs:['Unlocked','Locked'],arch:0};cl();draw()">Reset</a></p><label>Date (trip start)</label><div class="row"><input id="f1" type="date" value="${f.from}"><input id="f2" type="date" value="${f.to}"></div><label>Owner</label><select id="f3"><option value="">Any</option>${ow.map(x=>`<option ${f.ow==x?'selected':''}>${esc(x)}</option>`).join('')}</select><label>Type</label>${['Regular Trip','Group Trip','Sub-Trip'].map(x=>`<label class="ck" style="margin:0"><input type="checkbox" class="ft" value="${x}" ${f.ty.includes(x)?'checked':''}><span>${x}</span></label>`).join('')}<label>Commission status</label>${['Unlocked','Locked'].map(x=>`<label class="ck" style="margin:0"><input type="checkbox" class="fc" value="${x}" ${f.cs.includes(x)?'checked':''}><span>${x}</span></label>`).join('')}<label>More</label><label class="ck" style="margin:0"><input type="checkbox" id="f4" ${f.arch?'checked':''}><span>Include archived trips</span></label>`,'Show results',()=>{S.trf={from:$('#f1').value,to:$('#f2').value,ow:$('#f3').value,ty:[...document.querySelectorAll('.ft')].filter(x=>x.checked).map(x=>x.value),cs:[...document.querySelectorAll('.fc')].filter(x=>x.checked).map(x=>x.value),arch:$('#f4').checked?1:0};cl();draw()})}
function shv(i){const t=S.sh[i];S.menu=null;dlg(esc(t.n),`<p>Owner: ${esc(t.ow)}<br>Client: ${t.grp?'–':esc(t.cl)+' ('+t.pp+' people)'}<br>Status: ${t.st}<br>Dates: ${t.d}<br>${t.pub?'Published to the client portal':'Not published'}</p><p class="mu">Demo trip. Not real.</p>`,'',null)}
function shx(i,a){const t=S.sh[i];S.menu=null;if(a=='unpub'){t.pub=0;toast('Unpublished (preview only)')}else{S.trash.push(S.sh.splice(i,1)[0]);toast('Moved to trash (preview only)')}draw()}
function shg(i){const t=S.sh[i],g=S.sh.filter(x=>x.grp);S.menu=null;if(!g.length){toast('There are no group trips to move this into');draw();return}dlg('Move to group',`<label>Group trip</label><select id="a1">${g.map(x=>`<option>${esc(x.n)}</option>`).join('')}</select>`,'Move',()=>{const n=$('#a1').value,gt=S.sh.find(x=>x.grp&&x.n==n);gt.sub++;S.sh.splice(S.sh.indexOf(t),1);cl();toast('Moved to '+n+' (preview only)');draw()})}
function trt(){S.menu=null;draw();dlg('Trash',S.trash.length?S.trash.map((t,i)=>`<div class="ts"><span style="flex:1">${esc(t.n)}</span><button class="btn o s" onclick="trr(${i})">Restore</button></div>`).join(''):'<p class="mu">The trash is empty.</p>','',null)}
function trr(i){S.sh.push(S.trash.splice(i,1)[0]);cl();toast('Restored');draw()}
function tst(v){const t=trp();if(v=='Archived')t.arch=1;else{t.arch=0;t.s=Object.keys(SL).find(k=>SL[k]==v)||t.s}tin(t).log.push('Status set to '+v);toast('Status updated (preview only)');draw()}
function tpub(){}
function tdup(){const t=trp(),id='t'+Date.now(),c=JSON.parse(JSON.stringify(t));c.id=id;c.n=t.n+' (copy)';c.s='Draft';S.trips.unshift(c);if(S.itin[t.id])S.itin[id]=JSON.parse(JSON.stringify(S.itin[t.id]));S.cur=id;S.menu=null;toast('Trip duplicated');draw()}
function tdel(){const t=trp();S.menu=null;dlg('Delete trip?',`<p>${esc(t.n)} will be removed from your trips in this preview.</p>`,'Delete trip',()=>{S.trips=S.trips.filter(x=>x.id!=t.id);cl();toast('Trip deleted (preview only)');go('trips')})}
function tgrp(){S.menu=null;const g=S.sh.filter(x=>x.grp);dlg('Move to group',g.length?`<label>Group trip</label><select id="a1">${g.map(x=>`<option>${esc(x.n)}</option>`).join('')}</select>`:'<p class="mu">There are no group trips yet.</p>',g.length?'Move':'',()=>{const n=$('#a1').value,gt=S.sh.find(x=>x.grp&&x.n==n);gt.sub++;cl();toast('Moved to '+n+' (preview only)');draw()})}
function tadd(){dlg('Add a traveler','<label>Full name</label><input id="a1"><label>Email (optional)</label><input id="a2" type="email">','Add traveler',()=>{const n=$('#a1').value.trim(),e=$('#a2').value.trim();if(!n){$('#er').textContent='Enter the traveler’s name.';return}if(e&&!/^\S+@\S+\.\S+$/.test(e)){$('#er').textContent='Enter a valid email or leave it empty.';return}const t=tin(trp());t.trv.push([n,e]);t.tv=t.trv.length;cl();toast('Traveler added (demo)');draw()})}
function trem(i){const t=tin(trp());t.trv.splice(i,1);t.tv=t.trv.length;draw()}
function tset(){}
function tcol(){}
function mn(k){S.menu=S.menu==k?null:k;draw()}
function go(p){if(p=='trip'&&S.pg!='trip')S.tsec='Overview';if(p=='libit'&&S.pg!='libit'&&S.pg!='tpl'){S.ifp=[];S.ipg=1}if(p=='libph'&&S.pg!='libph')S.pfp=[];if(p=='libau'&&S.pg!='libau'&&S.pg!='autoed')S.afp=[];S.pg=p;S.menu=null;S.dr=0;location.hash=p;draw();scrollTo(0,0)}
function tg(){const r=document.documentElement;r.dataset.theme=r.dataset.theme=='dark'?'light':'dark';S.menu=null;draw()}
function cust(){dlg('Customize dashboard',[['c','Summary cards'],['ch','Charts'],['l','Gross sales chart'],['g','Goals'],['a','Active authorizations'],['t','Traveling & leaving soon']].map(x=>`<label class="ts"><input type="checkbox" ${S.w[x[0]]?'checked':''} onchange="S.w['${x[0]}']=this.checked?1:0"><span>${x[1]}</span></label>`).join(''),'Done',()=>{cl();draw()})}
function bkd(r){const b=S.bk.find(x=>x[0]==r);dlg('Booking '+r,`<p>${esc(b[1])} · ${esc(b[2])}<br>${b[3]} · ${$$(b[4])} · ${pl(b[5])}</p><p class="mu">Demo record. No real supplier booking exists.</p>`,'Mark as paid (demo)',()=>{b[5]='Paid';cl();draw()})}
function addS(){dlg('New supplier',`<label>Name</label><input id="a1"><label>Website</label><input id="a3"><label>Category</label><select id="a2">${SCAT.map(c=>`<option>${c}</option>`).join('')}</select>`,'Save supplier',()=>{const n=$('#a1').value.trim();if(!n){$('#er').textContent='Enter a supplier name.';return}S.sup.unshift([n,0,'S'+Math.random().toString(36).slice(2,9),$('#a2').value,'',1,$('#a3').value.trim()]);cl();toast('Supplier added');draw()})}
function addC(){dlg('Add client','<label>Full name</label><input id="a1"><label>Email</label><input id="a2" type="email">','Save client',()=>{const n=$('#a1').value.trim(),e=$('#a2').value.trim();if(!n||!/^\S+@\S+\.\S+$/.test(e)){$('#er').textContent='Enter a name and a valid email.';return}S.clients.unshift({id:S.clients.length,n,e,s:'Lead',l:'—'});S.clients.forEach((c,i)=>c.id=i);cl();toast('Client added');draw()})}
function addT(){dlg('New trip',`<label>Trip name</label><input id="a1"><label>Client</label><select id="a2">${S.clients.filter(c=>c.s!='Archived').map(c=>`<option>${esc(c.n)}</option>`).join('')}</select>`,'Create trip',()=>{const n=$('#a1').value.trim();if(!n){$('#er').textContent='Give the trip a name.';return}const id='t'+Date.now();S.trips.unshift({id,n,c:$('#a2').value,d:'Dates to be set',s:'Draft',v:0});S.cur=id;cl();toast('Trip created');go('trip')})}
function comp(s,t){obCompose('',{subj:s||'',to:t||''})}
function c2(){const c=S.clients[S.cc];c.s=c.s=='Archived'?'Active':'Archived';toast('Client '+(c.s=='Archived'?'archived':'restored'));draw()}
function mv(i,d){const a=itn().days[S.day].a,j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];draw()}
function delD(){const it=itn();if(it.days.length<2){toast('A trip needs at least one day');return}it.days.splice(S.day,1);S.day=0;draw()}
function addK(){const v=$('#nk').value.trim();if(!v){$('#er').textContent='Enter a task name to add it.';return}S.tasks.unshift({t:v,w:'General',d:'Nov 1',x:0});draw()}

