const mflt=()=>{const k=tb('em2',['Important','Inbox','Archived']),q=S.mq.toLowerCase();return S.mail.map((m,i)=>[m,i]).filter(x=>x[0][2].toLowerCase().includes(q)&&(k=='Archived'?x[0].ar:!x[0].ar&&(k=='Inbox'||x[0].imp)))};
const ml_=()=>{const l=mflt();return l.length?l.map(x=>`<div class="mi ${S.mi==x[1]?'on':''}" style="display:flex;gap:8px"><input type="checkbox" style="margin-top:4px" aria-label="Select conversation" ${S.msel[x[1]]?'checked':''} onchange="msl(${x[1]},this.checked)"><div style="flex:1;min-width:0;cursor:pointer" tabindex="0" onclick="S.mi=${x[1]};emr()"><div class="r1"><span>${x[0].imp?'':''}${esc(x[0][0])}</span><span>${x[0][1]}</span></div><div>${esc(x[0][2])}</div><div class="mu">${esc(x[0][3])}</div></div></div>`).join(''):'<p class="mu" style="text-align:center;margin-top:30px">No conversations</p>'};
const mb_=()=>{const n=Object.keys(S.msel).length;return n?`<div class="mbar"><button class="ib" aria-label="Clear selection" onclick="S.msel={};emr()">${ic('x',14)}</button><span><b>${n}</b> selected</span><span class="mu">Up to 500 at a time</span><button class="btn o s" onclick="mbulk(1)">Archive</button><button class="btn o s" onclick="mbulk(0)">Unarchive</button></div>`:''};
const mr_=()=>S.mi===null?`<div><p class="mu">No conversation selected</p><button class="btn o" onclick="comp()">+ New email</button></div>`:(m=>`<div class="mv"><h2 style="font-size:17px">${esc(m[2])}</h2><p class="mu">${esc(m[0])} · ${m[1]}</p><p>${esc(m[4])}</p><div class="row"><button class="btn o" onclick="comp('Re: '+S.mail[S.mi][2])">Reply</button><button class="btn o" onclick="S.mail[S.mi].imp=!S.mail[S.mi].imp;emr()">${m.imp?'Remove from Important':'Mark important'}</button><button class="btn o" onclick="mone()">${m.ar?'Unarchive':'Archive'}</button></div></div>`)(S.mail[S.mi]);
const emr=()=>{$('#mls').innerHTML=ml_();$('#mbr').innerHTML=mb_();$('#mrd').innerHTML=mr_()};
function msl(i,v){v?S.msel[i]=1:delete S.msel[i];emr()}
function msa(v){mflt().forEach(x=>v?S.msel[x[1]]=1:delete S.msel[x[1]]);emr()}
function mbulk(a){const n=Object.keys(S.msel).length;Object.keys(S.msel).forEach(i=>S.mail[i].ar=a);S.msel={};S.mi=null;toast((a?'Archived ':'Unarchived ')+n+' conversations');emr()}
