const LS_KEY='lti-proto-r26';
const uid=p=>(p||'id')+'-'+Math.random().toString(36).slice(2,8)+Date.now().toString(36).slice(-3);
/* ---------- dates (all ISO yyyy-mm-dd, computed in UTC to avoid TZ drift) ---------- */
const dP=s=>new Date(s+'T00:00:00Z');
const iso=d=>d.toISOString().slice(0,10);
const addD=(s,n)=>{const d=dP(s);d.setUTCDate(d.getUTCDate()+n);return iso(d)};
const dDiff=(a,b)=>Math.round((dP(b)-dP(a))/864e5);
const MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const fd=s=>{if(!s)return '–';const d=dP(s);return MON[d.getUTCMonth()]+' '+d.getUTCDate()+', '+d.getUTCFullYear()};
const fds=s=>{if(!s)return '–';const d=dP(s);return MON[d.getUTCMonth()]+' '+d.getUTCDate()};
const fdr=(a,b)=>a?(b?fds(a)+' – '+fd(b):fd(a)):'Dates to be set';
const legacyD=s=>{/* 'Oct 28' or 'Nov 14, 2026' → iso */if(!s)return '';const m=String(s).match(/([A-Z][a-z]{2})\w*\s+(\d+)(?:,\s*(\d{4}))?/);if(!m)return '';const mo=MON.indexOf(m[1]);if(mo<0)return '';return iso(new Date(Date.UTC(+(m[3]||2026),mo,+m[2])))};
const TODAY=()=>X.today;
const rel=s=>{if(!s)return '';const n=dDiff(TODAY(),s);return n==0?'today':n==1?'tomorrow':n==-1?'yesterday':n>0?'in '+n+' days':Math.abs(n)+' days ago'};
const nowStamp=()=>X.today+' '+new Date().toTimeString().slice(0,5);

/* ---------- the extension store (X) lives inside S so one save covers all ---------- */
let X=null;
const PERSIST=['tr_','aut','LG','ove','trips','itin','tasks','mail','cm','csh','sup','users','tags','notes','ctl','trash','sh','seg','cmp','sqs','cols_','lw','X','clients'];
function persist(){if(window.__resetting)return;try{S.LG=libSnapshot();const o={};PERSIST.forEach(k=>{if(S[k]!==undefined)o[k]=S[k]});localStorage.setItem(LS_KEY,JSON.stringify(o));X._saved=new Date().toTimeString().slice(0,8)}catch(e){X&&(X._saveErr=String(e&&e.message||e))}}
function restore(){try{const r=localStorage.getItem(LS_KEY);if(!r)return false;const o=JSON.parse(r);if(!o.X||o.X.v!==SCHEMA)return false;PERSIST.forEach(k=>{if(o[k]!==undefined)S[k]=o[k]});libRestore(o.LG);return true}catch(e){return false}}
function resetDemo(){dlg('Reset demo data','<p>All prototype changes (trips, tasks, automations, emails, payments, settings) return to the original sample data. This cannot be undone.</p>','Reset',()=>{window.__resetting=1;try{localStorage.removeItem(LS_KEY)}catch(e){}location.hash='dashboard';location.reload()})}
