const unread=()=>X.notifs.filter(n=>!n.read).length;
const curUser=()=>X.me;
function openRef(ref){if(!ref)return;const [k,id]=ref.split(':');if(k=='trip'){S.cur=id;go('trip')}else if(k=='contact'){S.cc=id;go('client')}else if(k=='auto'){X.ui.autoId=id;go('autobuild')}else if(k=='wf'){X.ui.wfId=id;go('workflows')}else if(k=='booking'){X.ui.bkOpen=id;go('bookings')}else if(k=='task')go('tasks');else if(k=='email'){X.ui.obOpen=id;go('outbox')}else if(k=='call'){go('callhist');setTimeout(()=>callDetail(id),30)}}
const refName=ref=>{if(!ref)return '';const [k,id]=ref.split(':');if(k=='trip'){const t=S.trips.find(x=>x.id==id);return t?t.n:'(deleted trip)'}if(k=='contact'){const c=cbyid(id);return c?(c.f+' '+c.l).trim():'(deleted contact)'}if(k=='booking')return id;if(k=='call'){const c=(X.calls||[]).find(x=>x.id==id);return c?(c.dir=='Inbound'?'Call from ':'Call to ')+(c.cid?refName('contact:'+c.cid):c.num):'Call'}return ref};

