function travSec(t){return cd('Travelers & permissions',`<p class="mu" style="font-size:12px">Permission modes control what each traveler can do on the client portal. Primary: approve, choose options, authorize payments. Full access: see everything incl. payments, comment & request changes. Limited: itinerary and their own documents only.</p>`+((t.tvx||[]).map((v,i)=>{const c=cbyid(v.cid)||{f:'?',l:''};return `<div class="ts" style="align-items:center"><span class="av2">${ini(c.f+' '+c.l)}</span><span style="flex:1"><a class="lk" onclick="S.cc='${v.cid}';go('client')">${esc(c.f+' '+c.l)}</a><div class="mu" style="font-size:12px">${esc(c.e||'No email')}${c.ph?' · '+esc(c.ph):''}</div></span>${callBtn(c.ph,v.cid,t.id,1)}${sel('',[['Primary','Primary traveler'],['Full','Full access'],['Limited','Limited access']],v.perm,`style="width:auto" aria-label="Permission" onchange="trvPerm(${i},this.value)"`)}<button class="btn o s" onclick="trp().tvx.splice(${i},1);logA('trip:'+trp().id,'Traveler removed','trip');draw()">Remove</button></div>`}).join('')||emp('users','No travelers','Add travelers from contacts.')),`<button class="btn s" onclick="trvAdd()">+ Add traveler</button>`)}
