function trvAdd(){const t=trp();dlg('Add traveler',`<label>Existing contact</label>${sel('tva',[['','— New contact —'],...S.cm.filter(c=>!(t.tvx||[]).some(v=>v.cid==c.id)).slice(0,80).map(c=>[c.id,(c.f+' '+c.l).trim()])],'')}<div class="g g2"><div><label>First name (new)</label><input id="tvf"></div><div><label>Last name (new)</label><input id="tvl"></div></div><label>Email (new)</label><input id="tve"><label>Permission</label>${sel('tvp',[['Full','Full access'],['Limited','Limited access'],['Primary','Primary traveler']],(t.tvx||[]).length?'Full':'Primary')}`,'Add',()=>{let id=val('tva');if(!id){if(!val('tvf'))return err('Choose a contact or enter a name.');id=uid('c');S.cm.unshift({id,f:val('tvf'),l:val('tvl'),e:val('tve'),t:'',ti:'',b:'',g:[],ty:'Traveler',mk:'Not opted',ann:'',pp:'',hh:[],prefs:{},loy:[],src:'Added to trip',created:TODAY()});fire('contact_created','contact',id)}t.tvx=t.tvx||[];if(val('tvp')=='Primary')t.tvx.forEach(x=>{if(x.perm=='Primary')x.perm='Full'});t.tvx.push({cid:id,perm:val('tvp')});if(!t.cid||val('tvp')=='Primary'){t.cid=id;t.c=refName('contact:'+id)}logA('trip:'+t.id,'Traveler added: '+refName('contact:'+id),'trip');cl();draw()})}
