/* ===================== Payments & authorizations ===================== */
const payState=p=>p.st=='Paid'?'Paid':p.st=='Void'?'Void':p.st=='Refunded'?'Refunded':p.auth=='authorized'?'Authorized':p.due<TODAY()?'Overdue':dDiff(TODAY(),p.due)<=14?'Due soon':p.auth=='requested'?'Auth requested':'Scheduled';
const DEMO_CARDS=['Demo Visa •••• 4242','Demo Mastercard •••• 4444','Demo Amex •••• 0005','Demo bank transfer (ACH) •••• 6789'];
function paySchedule(t,mode,P){const l=tripPays(t.id).sort((a,b)=>a.due<b.due?-1:1),tot=sum(l.filter(p=>p.st!='Void'),p=>p.amt),paid=sum(l,p=>p.paid);
 const rows=l.map(p=>{const s=payState(p),b=X.bookings.find(x=>x.ref==p.bk);return `<tr><td>${esc(p.label)}<div class="mu" style="font-size:12px">${b?esc(b.supplier):''}</div></td><td>${fd(p.due)}<div class="mu" style="font-size:12px">${p.st=='Paid'?'':rel(p.due)}</div></td><td>${mny(p.amt)}</td><td>${mny(p.paid)}</td><td>${mny(p.st=='Void'?0:p.amt-p.paid)}</td><td>${pill(s,s.replace(/\s/g,''))}${p.method?`<div class="mu" style="font-size:11px">${esc(p.method)}</div>`:''}</td><td>${mode=='client'?(p.st!='Paid'&&p.st!='Void'&&p.auth!='authorized'?(P&&P.pay?`<button class="btn g1 s" onclick="payAuth('${p.id}')">Authorize</button>`:'<span class="mu" style="font-size:12px">Primary traveler authorizes</span>'):''):`<div class="row" style="flex-wrap:nowrap">${p.st!='Paid'&&p.st!='Void'&&p.auth=='none'?`<button class="btn o s" onclick="payReq('${p.id}')" ${dis('fin.record')}>Request auth</button>`:''}${p.st!='Paid'&&p.st!='Void'?`<button class="btn s" onclick="payRecord('${p.id}')" ${dis('fin.record')}>Record payment</button>`:''}${p.st=='Paid'?`<button class="btn o s" onclick="payRefund('${p.id}')" ${dis('fin.record')}>Refund</button>`:''}</div>`}</td></tr>`}).join('');
 return `${mode=='client'?'<h2 style="font-size:15px">Payment schedule</h2>':''}<div class="g g4" style="margin-bottom:10px">${kpi('Trip total',mny(tot))}${kpi('Paid',mny(paid))}${kpi('Balance',mny(tot-paid))}${kpi('Next due',(l.find(p=>p.st!='Paid'&&p.st!='Void')||{}).due?fd(l.find(p=>p.st!='Paid'&&p.st!='Void').due):'—')}</div>${l.length?`<div class="cd"><div class="tw"><table class="t2"><thead><tr><th>Payment</th><th>Due</th><th>Amount</th><th>Paid</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></div>`:emp('card','No payment schedule','Add payments from a booking.')}${mode=='client'?`<p class="mu" style="font-size:12px">${demoTag('Demo')} Authorizations are simulated with masked demo methods. No card details are collected and no money moves.</p>`:`<div class="row"><button class="btn o s" onclick="invNew('${t.id}')" ${dis('fin.record')}>Generate invoice</button><button class="btn o s" onclick="wfApplyDlg('wf7','trip','${t.id}')">Payment reminder workflow</button></div>`}`}
function payReq(id){if(!guard('fin.record'))return;const p=X.pay.find(x=>x.id==id),t=tripById(p.tripId),c=ctxOf('trip',t.id);p.auth='requested';p.hist.push({at:TODAY(),txt:'Authorization requested'});X.outbox.unshift({id:uid('em'),to:c.contact?c.contact.e:'(no email)',ref:'trip:'+t.id,subj:`Please authorize ${mny(p.amt)} for ${t.n}`,body:render(`Hi {{client.first_name}},\n\nPlease review and authorize ${mny(p.amt)} (${p.label}) due ${fd(p.due)} on your trip page: {{trip.link}}\n\n{{advisor.signature}}`,c),st:'Sent',at:nowStamp(),auto:'',runAt:''});logA('trip:'+t.id,`Authorization requested for ${p.label} (${mny(p.amt)})`,'finance');toast('Authorization request emailed (demo outbox)');draw()}
function payAuth(id){const p=X.pay.find(x=>x.id==id),t=tripById(p.tripId);dlg('Authorize payment',`<div class="dm">Simulated authorization — choose a masked demo method. Never enter real card numbers.</div><p><b>${mny(p.amt-p.paid)}</b> · ${esc(p.label)} · due ${fd(p.due)}</p><label>Payment method</label>${sel('pam',DEMO_CARDS,DEMO_CARDS[0])}<label class="ck" style="font-size:13px;margin-top:10px"><input type="checkbox" id="pac"> I authorize ${esc(X.set.agency)} to charge this amount on or after the due date (demo consent).</label>`,'Authorize',()=>{if(!val('pac'))return err('Please tick the consent box to authorize.');p.auth='authorized';p.method=val('pam');p.hist.push({at:TODAY(),txt:'Authorized by '+viewerName(t)+' · '+p.method});logA('trip:'+t.id,`${viewerName(t)} authorized ${mny(p.amt-p.paid)} (${p.label})`,'portal');notify(`${viewerName(t)} authorized ${mny(p.amt-p.paid)} on ${t.n}`,'trip:'+t.id,'payment');cl();fire('client_authorizes_payment','trip',t.id);toast('Payment authorized (demo) — no charge was made');draw()})}
function payRecord(id){if(!guard('fin.record'))return;const p=X.pay.find(x=>x.id==id);dlg('Record payment',`<p class="mu">${esc(p.label)} · balance ${mny(p.amt-p.paid)}</p><label>Amount received</label><input id="a1" type="number" min="0" step="0.01" value="${p.amt-p.paid}"><label>Method</label>${sel('a2',p.method?[p.method,...DEMO_CARDS]:DEMO_CARDS,p.method)}<label>Date</label><input id="a3" type="date" value="${TODAY()}">`,'Record',()=>{const a=+val('a1');if(!(a>0))return err('Enter an amount greater than zero.');if(a>p.amt-p.paid+0.001)return err('That is more than the balance ('+mny(p.amt-p.paid)+').');p.paid=Math.round((p.paid+a)*100)/100;p.method=val('a2');if(p.paid>=p.amt)p.st='Paid';p.hist.push({at:val('a3'),txt:`Payment recorded ${mny(a)} · ${p.method}`});logA('trip:'+p.tripId,`Payment recorded: ${mny(a)} (${p.label})`,'finance');cl();draw()})}
function payRefund(id){if(!guard('fin.record'))return;const p=X.pay.find(x=>x.id==id);dlg('Record refund',`<label>Refund amount</label><input id="a1" type="number" min="0" value="${p.paid}"><label>Reason</label><input id="a2">`,'Record refund',()=>{const a=+val('a1');if(!(a>0)||a>p.paid)return err('Enter an amount up to '+mny(p.paid)+'.');X.refunds.unshift({id:uid('rf'),bk:p.bk,amt:a,at:TODAY(),why:val('a2')||'—',method:p.method});p.paid-=a;if(p.paid<=0){p.st='Refunded'}else p.st='Scheduled';p.hist.push({at:TODAY(),txt:'Refund '+mny(a)});logA('trip:'+p.tripId,'Refund recorded '+mny(a),'finance');cl();draw()})}
function payAdd(ref){if(!guard('fin.record'))return;const b=X.bookings.find(x=>x.ref==ref);dlg('Add payment to '+ref,`<label>Label</label>${sel('a1',['Deposit','Installment','Final balance','Paid in full'],'Installment')}<label>Amount</label><input id="a2" type="number" min="0"><label>Due date</label><input id="a3" type="date" value="${addD(TODAY(),14)}">`,'Add',()=>{const a=+val('a2');if(!(a>0))return err('Enter an amount.');X.pay.push({id:uid('pay'),bk:ref,tripId:b.tripId,label:val('a1'),amt:a,due:val('a3'),paid:0,st:'Scheduled',auth:'none',method:'',hist:[{at:TODAY(),txt:'Created'}]});logA('trip:'+b.tripId,`Payment added to ${ref}: ${mny(a)} due ${fd(val('a3'))}`,'finance');cl();draw()})}
Pg.payments=()=>{if(!can('fin.view'))return hd('Payments')+emp('card','Restricted for your role','Switch demo role to Owner, Admin or Advisor.');const k=tb('pay',['Schedule','Authorizations','History','Refunds','Invoices']),L=X.pay.filter(p=>p.st!='Void').sort((a,b)=>a.due<b.due?-1:1),out=L.filter(p=>p.st!='Paid'&&p.st!='Refunded');
 let b='';if(k=='Schedule'){const f=X.ui.pf||'open',l=f=='open'?out:f=='overdue'?out.filter(p=>p.due<TODAY()):L;b=`<div class="seg" style="margin-bottom:10px">${[['open','Outstanding'],['overdue','Overdue'],['all','All']].map(x=>`<button class="${f==x[0]?'on':''}" onclick="X.ui.pf='${x[0]}';draw()">${x[1]}</button>`).join('')}</div>`+(l.length?`<div class="cd"><div class="tw"><table class="t2"><thead><tr><th>Trip</th><th>Payment</th><th>Booking</th><th>Due</th><th>Amount</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody>${l.map(p=>{const s=payState(p),t=tripById(p.tripId)||{n:'?'};return `<tr><td><a class="lk" onclick="S.cur='${p.tripId}';S.tsec='Payments';go('trip')">${esc(t.n)}</a></td><td>${esc(p.label)}</td><td>${esc(p.bk)}</td><td>${fd(p.due)}</td><td>${mny(p.amt)}</td><td>${mny(p.amt-p.paid)}</td><td>${pill(s,s.replace(/\s/g,''))}</td><td><div class="row" style="flex-wrap:nowrap">${p.st!='Paid'&&p.auth=='none'?`<button class="btn o s" onclick="payReq('${p.id}')">Request auth</button>`:''}${p.st!='Paid'?`<button class="btn s" onclick="payRecord('${p.id}')">Record</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div></div>`:emp('card','Nothing outstanding','All scheduled payments are paid.'))}
 if(k=='Authorizations'){const l=X.pay.filter(p=>p.auth!='none'&&p.st!='Void');b=l.length?tbl(['Trip','Payment','Amount','State','Method','Last update'],l.map(p=>[esc((tripById(p.tripId)||{}).n||''),esc(p.label),mny(p.amt),pill(p.auth=='authorized'?(p.st=='Paid'?'Captured':'Authorized'):'Requested',p.auth=='authorized'?'Paid':'Pending'),esc(p.method||'—'),esc((p.hist[p.hist.length-1]||{}).txt||'')])):emp('card','No authorizations','Request one from a payment.')}
 if(k=='History'){const l=X.pay.flatMap(p=>p.hist.map(h=>({p,h}))).sort((a,b)=>a.h.at<b.h.at?1:-1);b=l.length?tbl(['Date','Trip','Payment','Event'],l.slice(0,80).map(x=>[esc(x.h.at),esc((tripById(x.p.tripId)||{}).n||''),esc(x.p.label),esc(x.h.txt)])):emp('refresh','No history','')}
 if(k=='Refunds')b=cd('Refund records',X.refunds.length?tbl(['Date','Booking','Amount','Method','Reason'],X.refunds.map(r=>[fd(r.at),r.bk,mny(r.amt),esc(r.method||''),esc(r.why)])):emp('card','No refunds',''),'',1);
 if(k=='Invoices')b=cd('Invoices',X.invoices.length?tbl(['Invoice','Trip','Date','Total','Status',''],X.invoices.map(v=>[v.id,esc((tripById(v.tripId)||{}).n||''),fd(v.at),mny(sum(v.lines,l=>l[1])),pill(v.st.replace(' (demo)',''),'Sent'),`<button class="btn o s" onclick="invView('${v.id}')">Preview</button>`])):emp('file','No invoices',''),`<button class="btn s" onclick="invNew()" ${dis('fin.record')}>Generate invoice</button>`,1);
 return hd('Payments & authorizations',`<button class="btn o" onclick="wfById('wf7')&&(X.ui.wfId='wf7',go('workflows'))">Reminder workflow</button><button class="btn" onclick="invNew()" ${dis('fin.record')}>Generate invoice</button>`,'Deposits, installments, balances and simulated client authorizations')+DM('Demo: no real card data is collected or stored, and no transactions are processed.')+
 `<div class="g g5" style="margin-bottom:14px">${kpi('Scheduled total',$$(sum(L,p=>p.amt)))}${kpi('Collected',$$(sum(L,p=>p.paid)))}${kpi('Outstanding',$$(sum(out,p=>p.amt-p.paid)))}${kpi('Overdue',out.filter(p=>p.due<TODAY()).length,'',"S.tab.pay='Schedule';X.ui.pf='overdue';draw()")}${kpi('Awaiting authorization',X.pay.filter(p=>p.auth=='requested'&&p.st!='Paid').length,'',"S.tab.pay='Authorizations';draw()")}</div>`+tabs('pay',['Schedule','Authorizations','History','Refunds','Invoices'])+b};
function invNew(tid){if(!guard('fin.record'))return;dlg('Generate invoice',`<label>Trip</label>${sel('iv1',S.trips.filter(t=>tripPays(t.id).length).map(t=>[t.id,t.n]),tid||S.cur)}<label class="ck" style="font-size:13px;margin-top:8px"><input type="checkbox" id="iv2" checked> Only unpaid balances</label>`,'Generate',()=>{const t=tripById(val('iv1')),ps=tripPays(t.id).filter(p=>p.st!='Void'&&(!val('iv2')||p.st!='Paid'));if(!ps.length)return err('Nothing to invoice for this trip.');const id='INV-2026-'+String(31+X.invoices.length).padStart(3,'0');X.invoices.unshift({id,tripId:t.id,at:TODAY(),lines:ps.map(p=>[`${(X.bookings.find(b=>b.ref==p.bk)||{supplier:''}).supplier} — ${p.label} (due ${fd(p.due)})`,p.amt-p.paid]),st:'Draft'});logA('trip:'+t.id,'Invoice '+id+' generated','finance');cl();invView(id)})}
function invView(id){const v=X.invoices.find(x=>x.id==id),t=tripById(v.tripId),c=t&&t.cid?cbyid(t.cid):null;dlgW('Invoice '+id,`<div class="inv-print" id="invp"><div class="row sp"><img src="${X.set.logo||LOGO}" alt="" style="height:44px"><div style="text-align:right"><b style="font-size:18px">INVOICE</b><div class="mu">${id} · ${fd(v.at)}</div></div></div><div class="g g2" style="margin:14px 0"><div><span class="mu" style="font-size:12px">From</span><div><b>${esc(X.set.agency)}</b><br>${esc(X.set.agencyEmail)}<br>${esc(X.set.agencyPhone)}</div></div><div><span class="mu" style="font-size:12px">Bill to</span><div><b>${esc(c?(c.f+' '+c.l):t.c)}</b><br>${esc(c?c.e:'')}<br>Trip: ${esc(t.n)}</div></div></div><table><thead><tr><th>Description</th><th style="text-align:right">Amount</th></tr></thead><tbody>${v.lines.map(l=>`<tr><td style="white-space:normal">${esc(l[0])}</td><td style="text-align:right">${mny(l[1])}</td></tr>`).join('')}<tr><td><b>Total due</b></td><td style="text-align:right"><b>${mny(sum(v.lines,l=>l[1]))}</b></td></tr></tbody></table><p class="mu" style="font-size:11px;margin-top:14px">Demo invoice generated by the LTI Advisor prototype. Not a tax document. Pay via your trip page (simulated).</p></div>`,v.st=='Draft'?'Mark sent (demo)':null,()=>{v.st='Sent (demo)';logA('trip:'+v.tripId,'Invoice '+id+' marked sent','finance');cl();draw()},720);const f=document.querySelector('#ov [role=dialog] > .row:last-child');if(f){const b=document.createElement('button');b.className='btn o';b.textContent='Print / save as PDF';b.onclick=()=>{document.body.classList.add('printing-inv');window.print();setTimeout(()=>document.body.classList.remove('printing-inv'),500)};f.insertBefore(b,f.lastChild)}}

/* ===================== Commission & back office ===================== */
const cmStats=()=>({exp:sum(X.comm.filter(c=>c.st!='Cancelled'),c=>c.exp),rec:sum(X.comm,c=>c.rec),out:sum(X.comm.filter(c=>!['Cancelled','Paid out'].includes(c.st)),c=>Math.max(0,c.exp-c.rec)),paid:sum(X.payouts.filter(p=>p.st=='Paid'),p=>p.net)});
const readyToPay=ag=>X.comm.filter(c=>(c.st=='Matched'||c.st=='Received')&&!c.payout&&(!ag||c.agent==ag));
Pg.commission=()=>{if(!can('fin.commission'))return hd('Commission')+emp('dollar','Restricted for your role','Switch demo role to Owner, Admin or Advisor.');const k=tb('cmx',['Overview','Expected','Statements & reconciliation','Unclaimed','Payouts','Adjustments','Financial log']),s=cmStats();let b='';
 if(k=='Overview'){const bySup={},byAg={};X.comm.filter(c=>c.st!='Cancelled').forEach(c=>{bySup[c.supplier]=(bySup[c.supplier]||0)+c.exp;byAg[c.agent]=(byAg[c.agent]||0)+c.exp});b=`<div class="g g2"><div class="pn2"><h3>Expected commission by supplier</h3>${hb(Object.keys(bySup).map(x=>x.slice(0,14)),Object.values(bySup).map(Math.round))}</div><div class="pn2"><h3>Agent splits</h3>${Object.keys(X.splits).map(a=>`<div class="row sp ts"><span>${esc(a)}</span><span>${X.splits[a]}% agent / ${100-X.splits[a]}% agency · expected ${mny((byAg[a]||0)*X.splits[a]/100)}</span></div>`).join('')}<button class="btn o s" style="margin-top:8px" onclick="splitEdit()" ${dis('fin.payout')}>Edit splits</button></div></div><div class="pn2" style="margin-top:14px"><h3>Reconciliation workflow</h3><p class="mu">1. Import a supplier statement → 2. match each line to a booking (auto-suggested by confirmation number, then guest + amount) → 3. reconcile to mark commission received → 4. build an agent payout with splits and adjustments → 5. approve and mark paid.</p><button class="btn" onclick="S.tab.cmx='Statements & reconciliation';draw()">Go to statements</button></div>`}
 if(k=='Expected')b=`<div class="cd"><div class="tw"><table class="t2"><thead><tr><th>Booking</th><th>Trip</th><th>Supplier</th><th>Advisor</th><th>Expected</th><th>Received</th><th>Status</th><th></th></tr></thead><tbody>${X.comm.map(c=>{const bk=X.bookings.find(x=>x.ref==c.bk)||{};return `<tr><td><a class="lk" onclick="X.ui.bkOpen='${c.bk}';go('bookings')">${c.bk}</a></td><td>${esc((tripById(bk.tripId)||{}).n||'')}</td><td>${esc(c.supplier)}</td><td>${esc(c.agent)}</td><td>${mny(c.exp)}</td><td>${mny(c.rec)}</td><td>${pill(c.st)}</td><td>${c.st=='Expected'?`<button class="btn o s" onclick="cmManual('${c.id}')" ${dis('fin.reconcile')}>Mark received</button>`:''}</td></tr>`}).join('')}</tbody></table></div></div>`;
 if(k=='Statements & reconciliation'){const st=X.ui.stmt&&X.stmts.find(x=>x.id==X.ui.stmt);b=st?stmtView(st):`<div class="row" style="margin-bottom:10px"><button class="btn" onclick="stmtImport()" ${dis('fin.reconcile')}>Import supplier statement</button><span class="mu" style="font-size:12px">CSV paste or sample file · demo</span></div>`+(X.stmts.length?tbl(['Statement','Supplier','Date','Lines','Total','Status'],X.stmts.map(x=>[`<span class="lk">${x.id}</span>`,esc(x.supplier),fd(x.at),x.lines.length,mny(sum(x.lines,l=>l.amt)),pill(x.st)]),i=>`X.ui.stmt='${X.stmts[i].id}';draw()`):emp('file','No statements','Import one to reconcile.'))}
 if(k=='Unclaimed'){const l=X.unclaimed;b=cd('Unclaimed commission',l.length?tbl(['Statement','Confirmation','Guest','Amount',''],l.map((u,i)=>[u.stmt,esc(u.conf),esc(u.guest),mny(u.amt),`<button class="btn o s" onclick="unAssign(${i})" ${dis('fin.reconcile')}>Assign to booking</button> <button class="btn o s" onclick="unTask(${i})">Create claim task</button>`])):emp('dollar','Nothing unclaimed','Statement lines that match no booking land here.'),'',1)+`<p class="mu" style="font-size:12px">Also unclaimed: confirmed bookings past travel date with no commission received — ${X.comm.filter(c=>c.st=='Expected'&&(X.bookings.find(b=>b.ref==c.bk)||{}).date<TODAY()).length} found.</p>`}
 if(k=='Payouts'){const ags=Object.keys(X.splits);b=`<div class="g g${Math.min(ags.length,4)}" style="margin-bottom:14px">${ags.map(a=>{const r=readyToPay(a),g=sum(r,c=>c.rec),adj=sum(X.adj.filter(x=>x.agent==a&&!x.po),x=>x.amt);return `<div class="pn2"><h3>${esc(a)}</h3><div class="row sp"><span>Ready to pay (${r.length})</span><b>${mny(g)}</b></div><div class="row sp"><span>Split ${X.splits[a]}%</span><b>${mny(g*X.splits[a]/100)}</b></div><div class="row sp"><span>Adjustments</span><b>${mny(adj)}</b></div><div class="row sp" style="border-top:1px solid var(--ln);margin-top:6px;padding-top:6px"><span>Net payout</span><b>${mny(g*X.splits[a]/100+adj)}</b></div><button class="btn s" style="margin-top:8px" onclick="poCreate('${a}')" ${r.length?'':'disabled'} ${dis('fin.reconcile')}>Create payout</button></div>`}).join('')}</div>`+cd('Payout statements',X.payouts.length?tbl(['Payout','Advisor','Date','Gross','Split','Adj.','Net','Status',''],X.payouts.map(p=>[p.id,esc(p.agent),fd(p.at),mny(p.gross),p.pct+'%',mny(p.adj),mny(p.net),pill(p.st),`<button class="btn o s" onclick="poView('${p.id}')">Statement</button>${p.st=='Draft'?` <button class="btn s" onclick="poApprove('${p.id}')" ${dis('fin.payout')}>Approve</button>`:p.st=='Approved'?` <button class="btn s" onclick="poPaid('${p.id}')" ${dis('fin.payout')}>Mark paid</button>`:''}`])):emp('wallet','No payouts yet',''),'',1)}
 if(k=='Adjustments')b=cd('Agency adjustments',X.adj.length?tbl(['Date','Advisor','Amount','Reason','Applied'],X.adj.map(a=>[fd(a.at),esc(a.agent),mny(a.amt),esc(a.why),a.po||'Pending'])):emp('pct','No adjustments',''),`<button class="btn s" onclick="adjAdd()" ${dis('fin.reconcile')}>+ Adjustment</button>`,1);
 if(k=='Financial log'){const l=X.activity.filter(a=>a.ty=='finance');b=cd('Financial activity log',l.map(a=>`<div class="ts"><span class="aic">$</span><span style="flex:1">${esc(a.txt)}<div class="mu" style="font-size:12px">${esc(a.by)} · ${esc(a.at)}${a.ref?` · <a class="lk" onclick="openRef('${a.ref}')">${esc(refName(a.ref))}</a>`:''}</div></span></div>`).join('')||emp('refresh','No financial activity yet',''))}
 return hd('Commission & back office',`<button class="btn o" onclick="go('reporting2')">${ic('chart')} Reports</button>`,'Expected → statement → match → reconcile → payout')+`<div class="g g4" style="margin-bottom:14px">${kpi('Expected',mny(s.exp))}${kpi('Received',mny(s.rec))}${kpi('Outstanding',mny(s.out))}${kpi('Paid out to agents',mny(s.paid))}</div>`+tabs('cmx',['Overview','Expected','Statements & reconciliation','Unclaimed','Payouts','Adjustments','Financial log'])+b};
Pg.comm=Pg.commission;
function suggestMatch(l){const byConf=X.bookings.find(b=>b.conf&&b.conf==l.conf);if(byConf)return {ref:byConf.ref,why:'confirmation number'};const last=String(l.guest).split(',')[0].trim().toLowerCase(),c=X.comm.find(cm=>{const b=X.bookings.find(x=>x.ref==cm.bk);return b&&b.client.toLowerCase().includes(last)&&Math.abs(cm.exp-l.amt)<1&&cm.st=='Expected'});return c?{ref:c.bk,why:'guest + amount'}:null}
function stmtView(st){const open=st.st!='Reconciled';return `<div class="row sp" style="margin-bottom:10px"><button class="btn o s" onclick="X.ui.stmt='';draw()">← Statements</button>${open?`<div class="row"><button class="btn o s" onclick="stmtAuto('${st.id}')" ${dis('fin.reconcile')}>Accept all suggestions</button><button class="btn s" onclick="stmtRecon('${st.id}')" ${dis('fin.reconcile')}>Reconcile statement</button></div>`:pill('Reconciled')}</div>`+cd(`${st.id} · ${esc(st.supplier)} · ${fd(st.at)}`,`<div class="tw"><table class="t2"><thead><tr><th>Confirmation</th><th>Guest</th><th>Amount</th><th>Suggested match</th><th>Matched booking</th></tr></thead><tbody>${st.lines.map((l,i)=>{const sg=suggestMatch(l),cm=l.m?X.comm.find(c=>c.bk==l.m):null;return `<tr><td>${esc(l.conf)}</td><td>${esc(l.guest)}</td><td>${mny(l.amt)}</td><td>${sg?`${sg.ref} <span class="mu" style="font-size:12px">by ${sg.why}</span>`:'<span class="mu">No match found</span>'}</td><td>${open?sel('',[['','— Unmatched —'],['__un','Mark unclaimed'],...X.comm.filter(c=>c.st!='Cancelled').map(c=>[c.bk,c.bk+' · '+c.supplier+' · exp '+mny(c.exp)])],l.m,`style="width:auto" aria-label="Match line" onchange="X.stmts.find(x=>x.id=='${st.id}').lines[${i}].m=this.value;draw()" ${dis('fin.reconcile')}`):(l.m=='__un'?'Unclaimed':esc(l.m||'—'))}${cm&&Math.abs(cm.exp-l.amt)>=1?`<div style="font-size:12px;color:var(--wn)">Variance vs expected: ${mny(l.amt-cm.exp)}</div>`:''}</td></tr>`}).join('')}</tbody></table></div>`,'',1)}
function stmtAuto(id){const st=X.stmts.find(x=>x.id==id);let n=0;st.lines.forEach(l=>{if(!l.m){const s=suggestMatch(l);if(s){l.m=s.ref;n++}}});toast(n+' line'+(n==1?'':'s')+' matched from suggestions');draw()}
function stmtRecon(id){if(!guard('fin.reconcile'))return;const st=X.stmts.find(x=>x.id==id),un=st.lines.filter(l=>!l.m);dlg('Reconcile '+id,`<p>${st.lines.filter(l=>l.m&&l.m!='__un').length} matched · ${st.lines.filter(l=>l.m=='__un').length+un.length} will go to Unclaimed.</p>`,'Reconcile',()=>{st.lines.forEach(l=>{if(l.m&&l.m!='__un'){const c=X.comm.find(x=>x.bk==l.m);if(c){c.rec=Math.round((c.rec+l.amt)*100)/100;c.st=c.rec+0.5>=c.exp?'Matched':'Partially received';c.stmt=st.id;logA('booking:'+c.bk,`Commission ${mny(l.amt)} matched to ${c.bk} from ${st.id}`,'finance')}}else{X.unclaimed.push({stmt:st.id,conf:l.conf,guest:l.guest,amt:l.amt});l.m='__un'}});st.st='Reconciled';logA('',`Statement ${st.id} reconciled (${esc(st.supplier)})`,'finance');cl();toast('Statement reconciled');draw()})}
function stmtImport(){if(!guard('fin.reconcile'))return;dlgW('Import supplier statement',`<div class="fm"><label>Supplier</label>${sel('si1',[...new Set(S.sup.map(s=>s[0]))],'AmaWaterways')}<label>Statement lines (CSV: confirmation, guest, amount)</label><textarea id="si2" rows="6">AMA-77310,"Ruiz, H.",1158.50\n7712045,"Shah, D.",1180\n0000000,"Unknown, P.",95</textarea><p class="mu" style="font-size:12px">Sample data is pre-filled. Column mapping: 1 → confirmation, 2 → guest, 3 → commission amount.</p></div>`,'Import',()=>{const lines=val('si2').split('\n').map(r=>r.match(/("([^"]*)"|[^,]+)/g)).filter(Boolean).map(c=>({id:uid('ln'),conf:(c[0]||'').replace(/"/g,'').trim(),guest:(c[1]||'').replace(/"/g,'').trim(),amt:+String(c[2]||'0').replace(/[^0-9.]/g,''),m:''})).filter(l=>l.conf&&l.amt>0);if(!lines.length)return err('No valid lines found.');const id='ST-'+val('si1').replace(/[^A-Z]/g,'').slice(0,3)+'-'+Date.now().toString(36).slice(-4).toUpperCase();X.stmts.unshift({id,supplier:val('si1'),at:TODAY(),st:'Imported',lines});logA('',`Statement ${id} imported (${lines.length} lines)`,'finance');cl();X.ui.stmt=id;draw()},620)}
function cmManual(id){if(!guard('fin.reconcile'))return;const c=X.comm.find(x=>x.id==id);dlg('Mark commission received',`<label>Amount received</label><input id="a1" type="number" value="${c.exp}">`,'Save',()=>{c.rec=+val('a1')||0;c.st=c.rec+0.5>=c.exp?'Matched':'Partially received';c.stmt='manual';logA('booking:'+c.bk,'Commission marked received manually '+mny(c.rec),'finance');cl();draw()})}
function unAssign(i){const u=X.unclaimed[i];dlg('Assign unclaimed line',`<p>${esc(u.conf)} · ${esc(u.guest)} · ${mny(u.amt)}</p><label>Booking</label>${sel('a1',X.comm.map(c=>[c.bk,c.bk+' · '+c.supplier]),'')}`,'Assign',()=>{const c=X.comm.find(x=>x.bk==val('a1'));c.rec+=u.amt;c.st=c.rec+0.5>=c.exp?'Matched':'Partially received';X.unclaimed.splice(i,1);logA('booking:'+c.bk,'Unclaimed commission assigned '+mny(u.amt),'finance');cl();draw()})}
function unTask(i){const u=X.unclaimed[i];addTask({t:`Claim commission ${u.conf} (${u.guest}) with supplier`,due:addD(TODAY(),5),pri:'Medium',src:'Unclaimed commission',list:'Operations'});toast('Claim task created');draw()}
function poCreate(a){if(!guard('fin.reconcile'))return;const r=readyToPay(a),g=sum(r,c=>c.rec),adj=X.adj.filter(x=>x.agent==a&&!x.po),id='PO-'+String(8+X.payouts.length).padStart(4,'0');const po={id,agent:a,at:TODAY(),lines:r.map(c=>c.id),gross:g,pct:X.splits[a],adj:sum(adj,x=>x.amt),net:Math.round((g*X.splits[a]/100+sum(adj,x=>x.amt))*100)/100,st:'Draft'};X.payouts.unshift(po);r.forEach(c=>c.payout=id);adj.forEach(x=>x.po=id);logA('',`Payout ${id} drafted for ${a}: net ${mny(po.net)}`,'finance');toast('Payout drafted');draw()}
function poApprove(id){if(!guard('fin.payout'))return;const p=X.payouts.find(x=>x.id==id);p.st='Approved';logA('',`Payout ${id} approved`,'finance');draw()}
function poPaid(id){if(!guard('fin.payout'))return;const p=X.payouts.find(x=>x.id==id);p.st='Paid';p.lines.forEach(cid=>{const c=X.comm.find(x=>x.id==cid);if(c)c.st='Paid out'});logA('',`Payout ${id} marked paid (demo — no money moved)`,'finance');notify(`Payout ${id} to ${p.agent} marked paid (demo)`,'','finance');draw()}
function poView(id){const p=X.payouts.find(x=>x.id==id);dlgW('Payout statement '+id,`<div class="inv-print"><div class="row sp"><img src="${LOGO}" alt="" style="height:40px"><div style="text-align:right"><b>PAYOUT STATEMENT</b><div class="mu">${id} · ${fd(p.at)} · ${pill(p.st)}</div></div></div><p>Advisor: <b>${esc(p.agent)}</b> · split ${p.pct}%</p><table><thead><tr><th>Booking</th><th>Supplier</th><th style="text-align:right">Commission received</th><th style="text-align:right">Agent share</th></tr></thead><tbody>${p.lines.map(cid=>{const c=X.comm.find(x=>x.id==cid)||{};return `<tr><td>${c.bk}</td><td>${esc(c.supplier||'')}</td><td style="text-align:right">${mny(c.rec)}</td><td style="text-align:right">${mny(c.rec*p.pct/100)}</td></tr>`}).join('')}<tr><td colspan="3">Adjustments</td><td style="text-align:right">${mny(p.adj)}</td></tr><tr><td colspan="3"><b>Net payout</b></td><td style="text-align:right"><b>${mny(p.net)}</b></td></tr></tbody></table><p class="mu" style="font-size:11px">Demo statement — no funds are transferred.</p></div>`,null,null,640)}
function adjAdd(){dlg('Agency adjustment',`<label>Advisor</label>${sel('a1',Object.keys(X.splits),'')}<label>Amount (negative = deduction)</label><input id="a2" type="number" value="-25"><label>Reason</label><input id="a3">`,'Add',()=>{X.adj.unshift({id:uid('adj'),agent:val('a1'),amt:+val('a2')||0,why:val('a3')||'—',at:TODAY()});logA('','Adjustment added for '+val('a1')+': '+mny(+val('a2')),'finance');cl();draw()})}
function splitEdit(){dlg('Agent commission splits',Object.keys(X.splits).map((a,i)=>`<label>${esc(a)} — agent %</label><input id="sp${i}" type="number" min="0" max="100" value="${X.splits[a]}">`).join(''),'Save',()=>{Object.keys(X.splits).forEach((a,i)=>X.splits[a]=Math.max(0,Math.min(100,+val('sp'+i)||0)));logA('','Commission splits updated','finance');cl();draw()})}

