function supProfile(s){const n=s[0],x=X.supx[n]||(X.supx[n]={contact:'',email:'',phone:'',rate:10,notes:'',content:[]}),b=X.bookings.filter(y=>y.supplier==n),acts=Object.entries(X.itx).flatMap(([tid,it])=>it.opts.flatMap(o=>o.days.flatMap(d=>d.acts.filter(a=>a.supplier==n).map(a=>({tid,a}))))),pref=S.sup.some(y=>y[0]==n&&y[1]),ro=can('fin.record')?'':'disabled';
 return hd(esc(n),`<button class="btn o" onclick="X.ui.sp='';draw()">← Suppliers</button><button class="btn o" onclick="S.sup.filter(y=>y[0]=='${esc(n).replace(/'/g,"\\'")}').forEach(y=>y[1]=y[1]?0:1);draw()" ${ro}>${pref?'Remove preferred':'Mark preferred'}</button>`,`${esc(s[3])}${pref?' · <span class="pref">Preferred</span>':''}`)+
 `<div class="g g21"><div>${cd('Associated bookings',b.length?tbl(['Ref','Trip','Date','Status','Amount','Commission'],b.map(y=>[y.ref,esc((tripById(y.tripId)||{}).n||''),fd(y.date),pill(y.cxl?'Cancelled':y.st),mny(y.amt),mny(y.comm)]),i=>`X.ui.bkOpen='${b[i].ref}';go('bookings')`):emp('clip','No bookings',''),'',1)+cd('Associated itinerary activities',acts.length?acts.map(({tid,a})=>`<div class="ts"><span>${ic(ACT_TYPES[a.type].i,16)}</span><span style="flex:1">${esc(a.title)}<div class="mu" style="font-size:12px">${esc((tripById(tid)||{}).n||'')}</div></span></div>`).join(''):'<p class="mu">None.</p>')+cd('Saved supplier content',(x.content.map((c,i)=>`<div class="ts"><span>${ic('file',14)}</span><span style="flex:1">${esc(c)}</span><button class="btn o s" onclick="X.supx['${esc(n).replace(/'/g,"\\'")}'].content.splice(${i},1);draw()" ${ro}>Remove</button></div>`).join('')||'<p class="mu">No saved content.</p>'),`<button class="btn o s" onclick="dlg('Save content','<label>Title</label><input id=a1>','Save',()=>{if(val('a1'))X.supx['${esc(n).replace(/'/g,"\\'")}'].content.push(val('a1'));cl();draw()})" ${ro}>+ Add</button>`)}</div><div>${cd('Contact & terms',`<div class="fm">${[['contact','Contact person'],['email','Email'],['phone','Phone']].map(([k,l])=>`<label>${l}</label><input value="${esc(x[k]||'')}" onchange="X.supx['${esc(n).replace(/'/g,"\\'")}'].${k}=this.value" ${ro}>`).join('')}<label>Default commission rate %</label><input type="number" value="${x.rate}" onchange="X.supx['${esc(n).replace(/'/g,"\\'")}'].rate=+this.value" ${ro}><label>Category</label>${sel('',SCAT,s[3],`onchange="S.sup.filter(y=>y[0]=='${esc(n).replace(/'/g,"\\'")}').forEach(y=>y[3]=this.value);draw()" ${ro}`)}<label>Notes</label><textarea rows="3" onchange="X.supx['${esc(n).replace(/'/g,"\\'")}'].notes=this.value" ${ro}>${esc(x.notes||'')}</textarea></div>`)}${cd('Payments to supplier',`${b.map(y=>`<div class="row sp ts" style="font-size:13px"><span>${y.ref}</span><span>${mny(sum(X.pay.filter(p=>p.bk==y.ref),p=>p.paid))} collected of ${mny(y.amt)}</span></div>`).join('')||'<p class="mu">—</p>'}`)}</div></div>`}
