function calEvents(from,to){const ev=[],inR=d=>d&&d>=from&&d<=to;
 S.trips.filter(t=>t.st!='Archived'&&t.type!='sub').forEach(t=>{if(inR(t.sd))ev.push({d:t.sd,t:''+t.n+' departs',ty:'trip',ref:'trip:'+t.id});if(inR(t.ed))ev.push({d:t.ed,t:''+t.n+' returns',ty:'trip',ref:'trip:'+t.id})});
 const y0=+from.slice(0,4),y1=+to.slice(0,4);S.cm.filter(c=>c.ty=='Client'||c.ty=='Traveler').forEach(c=>{if(!c.created||c.src=='Tern import')return;for(let y=y0;y<=y1;y++){const b=bdNext(c.b,y);if(inR(b))ev.push({d:b,t:''+c.f+' '+c.l,ty:'bday',ref:'contact:'+c.id});const a=c.ann?bdNext(fd(c.ann),y):null;if(inR(a)&&c.hh&&!(c.hh[0]&&ev.some(e=>e.ty=='ann'&&e.d==a&&e.ref=='contact:'+c.hh[0].id)))ev.push({d:a,t:''+c.f+' '+c.l+' anniversary',ty:'ann',ref:'contact:'+c.id})}if(inR(c.pp))ev.push({d:c.pp,t:''+c.f+' '+c.l+' passport expires',ty:'pp',ref:'contact:'+c.id})});
 S.tasks.filter(k=>!k.x&&inR(k.due)).forEach(k=>ev.push({d:k.due,t:''+k.t,ty:'task',ref:'task:'+k.id,tid:k.id}));
 X.pay.filter(p=>p.st!='Paid'&&p.st!='Void'&&inR(p.due)).forEach(p=>ev.push({d:p.due,t:'$ '+mny(p.amt-p.paid)+' · '+((tripById(p.tripId)||{}).n||''),ty:'pay',ref:'trip:'+p.tripId}));
 allUpcoming().filter(u=>inR(u.run)).forEach(u=>ev.push({d:u.run,t:''+u.a.name+' · '+refName(recKey(u.rt,u.id)),ty:'auto',ref:'auto:'+u.a.id,time:(u.a.timing||{}).time}));
 X.sched.filter(s=>s.st=='pending'&&inR(s.runAt)).forEach(s=>ev.push({d:s.runAt,t:''+((autoById(s.auto)||{}).name||'')+' (delayed)',ty:'auto',ref:'auto:'+s.auto}));
 X.appts.filter(a=>inR(a.d)).forEach(a=>ev.push({d:a.d,t:''+a.s+' '+a.t,ty:'appt',ref:'appt:'+a.id,time:a.s,ap:a.id}));
 return ev.sort((a,b)=>a.d<b.d?-1:a.d>b.d?1:(a.time||'')<(b.time||'')?-1:1)}

