function cDel(id){if(!guard('contact.delete'))return;const c=cbyid(id),tr=cTrips(c).length;dlg('Delete contact',`<p>Delete ${esc(c.f+' '+c.l)}?${tr?` They appear on ${tr} trip(s); those trips keep their names but lose the link.`:''}</p>`,'Delete',()=>{S.cm=S.cm.filter(x=>x.id!=id);S.trips.forEach(t=>{t.tvx=(t.tvx||[]).filter(v=>v.cid!=id);if(t.cid==id)t.cid=''});logA('','Contact deleted: '+c.f+' '+c.l,'info');cl();go('contacts')})}
function cRelAdd(id){dlg('Link contact',`<label>Contact</label>${sel('a1',S.cm.filter(x=>x.id!=id).slice(0,100).map(x=>[x.id,(x.f+' '+x.l).trim()]),'')}<label>Relationship</label>${sel('a2',['Spouse','Partner','Child','Parent','Sibling','Friend','Travel companion','Assistant','Colleague'],'Spouse')}<label class="ck" style="font-size:13px"><input type="checkbox" id="a3" checked> Add the reverse link too</label>`,'Link',()=>{const c=cbyid(id),o=cbyid(val('a1'));c.hh=c.hh||[];if(c.hh.some(h=>h.id==o.id))return err('Already linked.');c.hh.push({id:o.id,r:val('a2')});if(val('a3')){const rev={Child:'Parent',Parent:'Child'}[val('a2')]||val('a2');o.hh=o.hh||[];if(!o.hh.some(h=>h.id==id))o.hh.push({id,r:rev})}logA('contact:'+id,'Relationship linked: '+o.f+' ('+val('a2')+')','info');cl();draw()})}
function cRelDel(id,i){const c=cbyid(id),h=c.hh[i],o=cbyid(h.id);c.hh.splice(i,1);if(o)o.hh=(o.hh||[]).filter(x=>x.id!=id);draw()}
addC=function(){if(!guard('contact.edit'))return;dlgW('New contact',`<div class="g g2 fm"><div><label>First name</label><input id="a1"></div><div><label>Last name</label><input id="a2"></div><div><label>Email</label><input id="a3" type="email"></div><div><label>Type</label>${sel('a4',['Client','Lead','Traveler'],'Client')}</div><div><label>Birthday</label><input id="a5" placeholder="e.g. Nov 4, 1978"></div><div><label>Passport expiration</label><input id="a6" type="date"></div><div><label>Tag</label><input id="a7" list="tgl2"><datalist id="tgl2">${allTags().map(t=>`<option>${esc(t)}</option>`).join('')}</datalist></div><div><label>Lead source</label>${sel('a8',['Website inquiry','Referral','Instagram','Repeat client','Event','Other'],'Referral')}</div></div><div id="dupw"></div>`,'Create contact',()=>{const f=val('a1'),e=val('a3');if(!f)return err('Enter a first name.');if(e&&!/^\S+@\S+\.\S+$/.test(e))return err('Enter a valid email.');const dup=S.cm.find(x=>(e&&x.e&&x.e.toLowerCase()==e.toLowerCase())||((x.f+' '+x.l).toLowerCase()==(f+' '+val('a2')).toLowerCase()));if(dup&&!S._dupOk){S._dupOk=1;$('#dupw').innerHTML=`<div class="dm">Possible duplicate: <b>${esc(dup.f+' '+dup.l)}</b> ${esc(dup.e||'')}. Click Create again to add anyway, or <a class="lk" onclick="cl();S.cc='${dup.id}';go('client')">open the existing contact</a>.</div>`;return}S._dupOk=0;
 const c={id:uid('c'),f,l:val('a2'),e,t:'',ti:'',b:val('a5'),g:val('a7')?[val('a7')]:[],ty:val('a4'),mk:'Not opted',ann:'',pp:val('a6'),hh:[],prefs:{},loy:[],src:val('a8'),created:TODAY()};S.cm.unshift(c);logA('contact:'+c.id,'Contact created','info');cl();const r=fire('contact_created','contact',c.id);toast('Contact created'+(r.length?' · '+r.length+' workflow/automation step(s) ran':''));S.cc=c.id;go('client')},640)};
cdup=function(){const g={};AC().forEach(c=>{const k1=c.e?'e:'+c.e.toLowerCase():null,k2='n:'+(c.f+' '+c.l).toLowerCase().replace(/\s+/g,' ').trim();[k1,k2].filter(Boolean).forEach(k=>(g[k]=g[k]||[]).push(c))});const grp=Object.entries(g).filter(([k,l])=>l.length>1&&new Set(l.map(x=>x.id)).size>1);S.menu=null;
 dlgW('Duplicate detection preview',grp.length?grp.map(([k,l])=>`<div class="pn2" style="margin-bottom:8px;padding:10px"><b>${k.startsWith('e:')?'Same email':'Same name'}: ${esc(k.slice(2))}</b>${l.map(c=>`<div class="ts" style="font-size:13px"><span style="flex:1">${esc(c.f+' '+c.l)} · ${esc(c.e||'no email')} <span class="mu">${c.o?'(shared by '+esc(c.o)+')':''} · ${cTrips(c).length} trips</span></span></div>`).join('')}<p class="mu" style="font-size:12px;margin:4px 0 0">Merge keeps the first record, combines tags & relationships, and re-links trips. Use Actions › Merge contacts to merge.</p></div>`).join(''):'<p class="mu">No likely duplicates found.</p>',null,null,620)};
cimp=function(){S.menu=null;draw();const sample='First Name,Last Name,Email Address,Birthday,Tags\nNora,Quinn,nora.q@example.com,Jun 3 1984,Honeymoon\nLeo,Park,leo.park@example.com,,Family\nAmelia,Hartwell,amelia@example.com,,VIP';dlgW('Import contacts · mapping preview',`<div class="fm"><label>Paste CSV (first row = headers)</label><textarea id="ci1" rows="5" oninput="cimpPv()">${sample}</textarea><div id="cimap"></div></div>`,'Import',()=>{const r=cimpParse();if(!r)return err('Paste at least a header and one row.');let n=0,d=0;r.rows.forEach(row=>{const o={};r.map.forEach((m,i)=>{if(m)o[m]=row[i]||''});if(!o.f&&!o.e)return;if(o.e&&S.cm.some(x=>x.e&&x.e.toLowerCase()==o.e.toLowerCase())){d++;return}S.cm.unshift({id:uid('c'),f:o.f||'',l:o.l||'',e:o.e||'',t:'',ti:'',b:o.b||'',g:o.g?o.g.split(/[;|]/).map(x=>x.trim()).filter(Boolean):[],ty:'Lead',mk:'Not opted',ann:'',pp:'',hh:[],prefs:{},loy:[],src:'CSV import',created:TODAY()});n++});logA('',`Contacts imported: ${n} added, ${d} duplicates skipped`,'info');cl();toast(`${n} contacts imported · ${d} duplicates skipped`);draw()},720);cimpPv()};
function cimpParse(){const t=val('ci1').trim().split('\n').map(r=>r.split(',').map(x=>x.trim()));if(t.length<2)return null;const guess=h=>/first/i.test(h)?'f':/last|surname/i.test(h)?'l':/mail/i.test(h)?'e':/birth/i.test(h)?'b':/tag/i.test(h)?'g':'';const map=t[0].map((h,i)=>{const e=document.getElementById('cm'+i);return e?e.value:guess(h)});return {head:t[0],rows:t.slice(1),map}}
function cimpPv(){const r=cimpParse(),el=$('#cimap');if(!el)return;if(!r){el.innerHTML='';return}const F=[['','— Skip —'],['f','First name'],['l','Last name'],['e','Email'],['b','Birthday'],['g','Tags']];el.innerHTML=`<label>Column mapping</label><div class="tw"><table><thead><tr>${r.head.map((h,i)=>`<th>${esc(h)}<br>${sel('cm'+i,F,r.map[i],'style="width:auto;font-size:12px" onchange="cimpPv()"')}</th>`).join('')}</tr></thead><tbody>${r.rows.slice(0,5).map(row=>`<tr>${row.map((v,i)=>`<td style="${r.map[i]?'':'color:var(--mu);text-decoration:line-through'}">${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="mu" style="font-size:12px">${r.rows.length} rows · ${r.rows.filter(row=>{const ei=r.map.indexOf('e');return ei>=0&&row[ei]&&S.cm.some(x=>x.e&&x.e.toLowerCase()==row[ei].toLowerCase())}).length} would be skipped as duplicates (same email).</p>`}

