function docTable(l,pre){const preS=JSON.stringify(pre||{}).replace(/"/g,"'");return cd(`Documents (${l.length})`,l.length?`<div class="tw"><table class="t2"><thead><tr><th>Name</th><th>Category</th><th>Linked to</th><th>Visibility</th><th>Added</th><th></th></tr></thead><tbody>${l.map(d=>`<tr><td><a class="lk" onclick="docPreview('${d.id}')">${d.kind=='pdf'?'':d.kind=='image'?'':''} ${esc(d.n)}</a><div class="mu" style="font-size:11px">${esc(d.size)}</div></td><td>${esc(d.cat)}</td><td style="font-size:12px">${[d.trip?'Trip: '+esc((tripById(d.trip)||{}).n||''):'',d.contact?'Contact: '+esc(refName('contact:'+d.contact)):'',d.bk?'Booking: '+d.bk:''].filter(Boolean).join('<br>')||'—'}</td><td>${d.vis=='client'?'<span class="tg" style="margin:0">Client-visible</span>':'<span class="tag">Internal</span>'}</td><td>${fd(d.at)}</td><td><div class="row" style="flex-wrap:nowrap"><button class="btn o s" onclick="docEdit('${d.id}')">Edit</button><button class="btn o s" onclick="docDel('${d.id}')">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`:emp('folder','No documents',''),`<button class="btn s" onclick="docUpload(${preS})">Upload</button>`,1)}
Pg.docs=()=>{const f=X.ui.df||(X.ui.df={q:'',cat:'',vis:'',trip:''}),l=X.docs.filter(d=>(!f.cat||d.cat==f.cat)&&(!f.vis||d.vis==f.vis)&&(!f.trip||d.trip==f.trip)&&d.n.toLowerCase().includes(f.q.toLowerCase()));return hd('Documents',`<button class="btn" onclick="docUpload({})">Upload</button>`,'Trip, client and booking documents with permission-based visibility')+`<div class="row" style="margin-bottom:12px">${searchBox('dq',f.q,"X.ui.df.q=this.value;clearTimeout(window._dq);window._dq=setTimeout(()=>{draw();const e=$('#dq');e.focus();e.setSelectionRange(e.value.length,e.value.length)},250)",'Search documents')}${sel('dc',[['','All categories'],...X.docCats],f.cat,`style="width:auto" aria-label="Category" onchange="X.ui.df.cat=this.value;draw()"`)}${sel('dv',[['','Any visibility'],['client','Client-visible'],['internal','Internal']],f.vis,`style="width:auto" aria-label="Visibility" onchange="X.ui.df.vis=this.value;draw()"`)}${sel('dt',[['','All trips'],...S.trips.map(t=>[t.id,t.n])],f.trip,`style="width:auto;max-width:220px" aria-label="Trip" onchange="X.ui.df.trip=this.value;draw()"`)}</div>`+docTable(l,{})+`<p class="mu" style="font-size:12px">Files you upload are kept in this browser only (small files stored as data, larger files as metadata). Client-visible documents appear on the client portal; internal ones never do.</p>`};
function docUpload(pre){pre=pre||{};dlgW('Upload document',`<div class="fm"><label>File</label><input type="file" id="du1"><div class="g g2"><div><label>Category</label>${sel('du2',X.docCats,pre.bk?'Travel documents':'Other')}</div><div><label>Visibility</label>${sel('du3',[['internal','Internal'],['client','Client-visible']],'internal')}</div><div><label>Trip</label>${sel('du4',[['','—'],...S.trips.map(t=>[t.id,t.n])],pre.trip||'')}</div><div><label>Contact</label>${sel('du5',[['','—'],...S.cm.filter(c=>c.ty!='Supplier contact').slice(0,80).map(c=>[c.id,c.f+' '+c.l])],pre.contact||'')}</div><div><label>Booking</label>${sel('du6',[['','—'],...X.bookings.map(b=>[b.ref,b.ref+' · '+b.supplier])],pre.bk||'')}</div></div><div class="dm" style="margin-top:10px">Demo: don’t upload real passports or personal documents.</div></div>`,'Upload',()=>{const inp=$('#du1'),file=inp&&inp.files&&inp.files[0];if(!file)return err('Choose a file.');const kind=/pdf/.test(file.type)?'pdf':/image/.test(file.type)?'image':'file',d={id:uid('d'),n:file.name,cat:val('du2'),kind,size:(file.size/1024).toFixed(0)+' KB',trip:val('du4'),contact:val('du5'),bk:val('du6'),vis:val('du3'),at:TODAY(),data:''};
 const fin=()=>{X.docs.unshift(d);logA(d.trip?'trip:'+d.trip:d.contact?'contact:'+d.contact:'','Document uploaded: '+d.n,'doc');cl();if(d.trip)fire('document_uploaded','trip',d.trip);toast('Uploaded (stored locally)');draw()};
 if(file.size<1500000&&kind!='file'){const r=new FileReader();r.onload=()=>{d.data=r.result;fin()};r.readAsDataURL(file)}else fin()},640)}
function docPreview(id){const d=X.docs.find(x=>x.id==id);if(!d)return;if(X.role=='Traveler'&&d.vis!='client')return toast('This document is internal to the agency');const body=d.data?(d.kind=='image'?`<img src="${d.data}" alt="${esc(d.n)}" style="max-width:100%;border-radius:6px">`:d.kind=='pdf'?`<object data="${d.data}" type="application/pdf" style="width:100%;height:60vh"><p class="mu">PDF preview not supported here.</p></object>`:'<p class="mu">No preview for this file type.</p>'):`<div class="docph"><div class="docpg">${d.kind=='pdf'?'':''}<b>${esc(d.n)}</b><p class="mu">Sample document — placeholder preview (no real file in the demo data).</p><div class="docl"></div><div class="docl"></div><div class="docl s"></div></div></div>`;dlgW(esc(d.n),body+`<p class="mu" style="font-size:12px;margin-top:8px">${esc(d.cat)} · ${d.vis=='client'?'Client-visible':'Internal'} · ${esc(d.size)}</p>`,null,null,760)}
function docEdit(id){const d=X.docs.find(x=>x.id==id);dlg('Edit document',`<label>Name</label><input id="de1" value="${esc(d.n)}"><label>Category</label>${sel('de2',X.docCats,d.cat)}<label>Visibility</label>${sel('de3',[['internal','Internal'],['client','Client-visible']],d.vis)}<label>Trip</label>${sel('de4',[['','—'],...S.trips.map(t=>[t.id,t.n])],d.trip)}`,'Save',()=>{if(!val('de1'))return err('Enter a name.');d.n=val('de1');d.cat=val('de2');d.vis=val('de3');d.trip=val('de4');logA(d.trip?'trip:'+d.trip:'','Document updated: '+d.n,'doc');cl();draw()})}
function docDel(id){const d=X.docs.find(x=>x.id==id);dlg('Delete document',`<p>Delete ${esc(d.n)}?</p>`,'Delete',()=>{X.docs=X.docs.filter(x=>x.id!=id);logA(d.trip?'trip:'+d.trip:'','Document deleted: '+d.n,'doc');cl();draw()})}

