Pg.content=()=>{const k=tb('ct',['Activities','Destination guides','Packing lists','Task templates','More libraries']),q=(X.ui.cq2||'').toLowerCase();let b='';
 if(k=='Activities')b=`<div class="row" style="margin-bottom:10px">${searchBox('cq2',X.ui.cq2,"X.ui.cq2=this.value;clearTimeout(window._cq);window._cq=setTimeout(()=>{draw();const e=$('#cq2');e.focus();e.setSelectionRange(e.value.length,e.value.length)},250)",'Search activities, places, tags')}<button class="btn s" onclick="libAdd()">+ Activity template</button></div><div class="gl" style="grid-template-columns:repeat(auto-fill,minmax(230px,1fr))">${X.lib.filter(a=>(a.title+a.loc+a.type+a.desc).toLowerCase().includes(q)).map(a=>`<div class="gt" style="cursor:default"><div class="cover sm" style="${cover(a.loc,a.img,70)}"><span>${ic(ACT_TYPES[a.type].i,16)}</span></div><b>${esc(a.title)}</b><span class="mu">${esc(a.loc||'Anywhere')} · ${esc(ACT_TYPES[a.type].l)}</span><span style="white-space:normal;font-size:12px">${esc(a.desc)}</span><span>${a.price?mny(a.price):''}</span><div class="row" style="margin-top:6px"><button class="btn o s" onclick="libUse('${a.id}')">Use in trip</button><button class="btn o s" onclick="X.lib=X.lib.filter(x=>x.id!='${a.id}');draw()">Delete</button></div></div>`).join('')}</div>`;
 if(k=='Destination guides')b=X.guides.map(g=>cd(esc(g.title)+' <span class="mu" style="font-weight:400">· '+esc(g.dest)+'</span>',g.sec.map((s,i)=>`<div class="fm"><label>${esc(s[0])}</label><textarea rows="2" onchange="X.guides.find(x=>x.id=='${g.id}').sec[${i}][1]=this.value">${esc(s[1])}</textarea></div>`).join(''),`<button class="btn o s" onclick="dlg('Attach guide to trip','${sel('ga',S.trips.map(t=>[t.id,t.n]),S.cur||'').replace(/'/g,"&#39;").replace(/"/g,'&quot;')}','Attach',()=>{ITX(val('ga')).guide='${g.id}';logA('trip:'+val('ga'),'Destination guide attached','trip');cl();toast('Guide attached')})">Use in trip</button>`)).join('')+`<button class="btn s" onclick="X.guides.push({id:uid('g'),dest:'New destination',title:'New guide',sec:[['Overview','']]});draw()">+ New guide</button>`;
 if(k=='Packing lists')b=X.packing.map(p=>cd(esc(p.n),`<div>${p.items.map((x,i)=>`<span class="chip">${esc(x)}<button aria-label="Remove" onclick="X.packing.find(y=>y.id=='${p.id}').items.splice(${i},1);draw()">×</button></span>`).join('')}</div><input placeholder="Add item + Enter" onkeydown="if(event.key=='Enter'&&this.value.trim()){X.packing.find(y=>y.id=='${p.id}').items.push(this.value.trim());draw()}">`)).join('')+`<button class="btn s" onclick="X.packing.push({id:uid('pk'),n:'New packing list',items:[]});draw()">+ New list</button>`;
 if(k=='Task templates')b=cd('Task templates',X.taskTpl.map((t,i)=>`<div class="row ts"><input value="${esc(t.n)}" style="flex:1" aria-label="Template name" onchange="X.taskTpl[${i}].n=this.value"><input type="number" value="${t.days}" style="width:70px" aria-label="Days" onchange="X.taskTpl[${i}].days=+this.value">${sel('',[['','days from today'],['start','days from trip start'],['end','days from trip end']],t.anchor||'',`style="width:auto" onchange="X.taskTpl[${i}].anchor=this.value"`)}${sel('',['High','Medium','Low'],t.pri,`style="width:auto" onchange="X.taskTpl[${i}].pri=this.value"`)}<button class="btn o s" onclick="X.taskTpl.splice(${i},1);draw()">Remove</button></div>`).join(''),`<button class="btn s" onclick="X.taskTpl.push({id:uid('tt'),n:'New task template',days:1,pri:'Medium'});draw()">+ Template</button>`);
 if(k=='More libraries')b=`<div class="gl">${[['Itinerary templates','libit','map'],['Photos & image assets','libph','image'],['Cruises','libcr','ship'],['Agency suppliers','libsu','bld'],['Email templates','emt','mail'],['Form templates','forms','copy'],['Workflow templates','workflows','globe'],['Automation templates','automations','bolt'],['Imported Tern automations','libau','bolt'],['Chat prompts','libch','chat']].map(x=>`<div class="gt" tabindex="0" onclick="${x[1]=='automations'?"S.tab.au='Templates';":''}go('${x[1]}')" onkeydown="if(event.key=='Enter')go('${x[1]}')">${ic(x[2],18)}<b>${x[0]}</b></div>`).join('')}</div>`;
 return hd('Content hub',``,'Reusable content for trips, emails, forms, tasks and workflows')+tabs('ct',['Activities','Destination guides','Packing lists','Task templates','More libraries'])+b};
function libAdd(){dlg('New activity template',`<label>Type</label>${sel('la1',Object.entries(ACT_TYPES).map(([k,v])=>[k,v.l]),'tour')}<label>Title</label><input id="la2"><label>Location</label><input id="la3"><label>Description</label><textarea id="la4" rows="2"></textarea><label>Price</label><input id="la5" type="number" value="0">`,'Save',()=>{if(!val('la2'))return err('Enter a title.');const a=A(val('la1'),val('la2'),val('la4'),{loc:val('la3'),price:+val('la5')||0});a.lib=1;X.lib.unshift(a);cl();draw()})}
function libUse(id){const a=X.lib.find(x=>x.id==id);dlg('Add “'+esc(a.title)+'” to a trip',`<label>Trip</label>${sel('lu1',S.trips.map(t=>[t.id,t.n]),S.cur||'')}<label>Day number</label><input id="lu2" type="number" min="1" value="1">`,'Add',()=>{const it=ITX(val('lu1')),o=it.opts[0],d=Math.max(1,+val('lu2')||1);while(o.days.length<d)o.days.push({id:uid('day'),t:'Day '+(o.days.length+1),acts:[]});const c=JSON.parse(JSON.stringify(a));c.id=uid('act');delete c.lib;o.days[d-1].acts.push(c);logA('trip:'+val('lu1'),'Library activity added: '+a.title,'trip');cl();toast('Added to '+(tripById(val('lu1'))||{}).n)})}

