const AI_NOTE='Demo AI · deterministic response built from mock data — no AI model was called.';
const DEST_IDEAS={Lisbon:[['tour','Tile-painting workshop','Hands-on azulejo class in Alfama.',90],['dining','Seafood lunch in Cascais','Fresh catch by the sea.',120],['excursion','Arrábida coast boat trip','Turquoise coves and dolphins.',210]],Amalfi:[['excursion','Sunset cruise along the coast','Prosecco at golden hour.',380],['tour','Ravello gardens walk','Villa Cimbrone & Villa Rufolo.',160],['dining','Limoncello tasting','Family producer in Minori.',70]],Kenya:[['excursion','Sunrise game drive','Big cats at first light.',0],['tour','Maasai village visit','Community-led cultural visit.',120],['excursion','Balloon safari','Champagne breakfast landing.',550]],Kyoto:[['tour','Nishiki market food walk','Pickles, tofu and matcha sweets.',140],['excursion','Fushimi Inari at dawn','Thousand torii gates without crowds.',90]],Danube:[['tour','Budapest thermal baths','Széchenyi evening soak.',60],['dining','Viennese coffee-house crawl','Sacher, Demel & Café Central.',75]],Rhine:[['excursion','Rüdesheim wine village','Riesling tasting & cable car.',95]],default:[['tour','Private city orientation walk','Get your bearings with a local guide.',180],['dining','Chef’s table dinner','Seasonal tasting menu.',260],['free','Free afternoon','Time to wander.',0]]};
function aiCtxTrip(){return tripById(X.ai.ctxTrip)||S.trips[0]}
function aiProp(kind,title,rec,before,after,payload,src){return {id:uid('ai'),kind,title,rec,before,after,payload,st:'pending',at:nowStamp(),src:src||'AI workspace'}}
function aiProposalFromAgent(kind,c,name){const t=c.trip,k=c.contact;if(kind=='summary')return aiProp('note','Trip/inquiry summary for '+(t?t.n:k.f),t?'trip:'+t.id:'contact:'+k.id,'(no summary)',aiSummary(t),{note:aiSummary(t)},'Automation: '+name);if(kind=='followups')return aiFollowups(t,'Automation: '+name);const e=aiEmail(t,k);return aiProp('email','Draft email: '+e.subj,t?'trip:'+t.id:'contact:'+k.id,'(no draft)',e.subj+'\n\n'+e.body,e,'Automation: '+name)}
const aiSummary=t=>{if(!t)return 'No trip on file.';const it=X.itx[t.id],o=it?it.opts[0]:null,bk=X.bookings.filter(b=>b.tripId==t.id);return `${t.n} — ${t.st}. ${fdr(t.sd,t.ed)} in ${t.dest||'TBD'} for ${(t.tvx||[]).length} traveler(s); owner ${t.ow}. ${o?o.days.length+' itinerary days, '+o.days.reduce((s,d)=>s+d.acts.length,0)+' activities':'No itinerary yet'}; ${bk.length} booking(s) worth ${mny(sum(bk,b=>b.amt))}. Payments: ${payStatus(t)}. Approval: ${it?it.appr.st:'none'}.`};
const aiEmail=(t,k)=>{const c=ctxOf(t?'trip':'contact',t?t.id:k.id),tone=X.set.aiTone;return {subj:render(t?'Next steps for {{trip.name}}':'Checking in, {{client.first_name}}',c),body:render(`Hi {{client.first_name}},\n\n${t?(t.st=='Inquiry'?'Thank you for sharing your ideas for {{trip.destination}}. I’m pulling together a first draft and will send it within a few days.':t.st=='Proposal'?'I hope you’ve had a chance to look through your proposal for {{trip.name}}. Let me know which option feels right, or what you’d like me to adjust.':'Everything is coming together for {{trip.name}} ({{trip.start_date}}). I’ll keep your trip page updated as confirmations arrive.'):'It’s been a little while — I’d love to hear where you’re dreaming of going next.'}\n\n{{advisor.signature}}`,c)+`\n\n[Tone: ${tone}]`,ref:t?'trip:'+t.id:'contact:'+k.id,to:c.contact?c.contact.e:''}};
function aiFollowups(t,src){const l=[];if(!t)return aiProp('tasks','Follow-up tasks','','',['No trip context'],{tasks:[]},src);const it=X.itx[t.id];if(t.st=='Inquiry')l.push('Schedule discovery call');if(it&&it.appr.st=='changes')l.push('Revise itinerary per client comments');if(payStatus(t)=='Overdue')l.push('Chase overdue payment');if(X.bookings.some(b=>b.tripId==t.id&&b.st=='Pending'&&!b.cxl))l.push('Confirm pending bookings');if(t.sd&&dDiff(TODAY(),t.sd)<30&&dDiff(TODAY(),t.sd)>0)l.push('Send final documents & packing tips');if(!l.length)l.push('Check in with client about trip excitement');return aiProp('tasks',`Suggested follow-up tasks for ${t.n}`,'trip:'+t.id,`${tripTasks(t).filter(x=>!x.x).length} open tasks`,l.map(x=>'+ '+x),{tasks:l,trip:t.id},src)}
function aiParse(txt){const lines=txt.split('\n').map(x=>x.trim()).filter(Boolean),days=[];let cur=null;lines.forEach(l=>{const dm=l.match(/^day\s*(\d+)\s*[:\-–]?\s*(.*)$/i);if(dm){cur={t:dm[2]||'Day '+dm[1],acts:[]};days.push(cur);return}if(!cur){cur={t:'Day 1',acts:[]};days.push(cur)}const time=(l.match(/\b(\d{1,2}:\d{2})\b/)||[])[1]||'',fl=l.match(/\b([A-Z]{2}|[A-Z]\d)\s?(\d{2,4})\b/),ty=fl&&/(flight|fly|depart|arriv|\bto\b)/i.test(l)?'flight':/(hotel|resort|palace|inn|lodge|ryokan|suite|check.?in)/i.test(l)?'hotel':/(cruise|ship|sail)/i.test(l)?'cruise':/(train|rail)/i.test(l)?'train':/(transfer|driver|pick.?up|car)/i.test(l)?'transfer':/(dinner|lunch|breakfast|restaurant|tasting)/i.test(l)?'dining':/(tour|walk|visit|museum|guide)/i.test(l)?'tour':/(free|leisure)/i.test(l)?'free':'custom';cur.acts.push({type:ty,title:l.replace(/^[-•*]\s*/,'').slice(0,80),time,f:fl&&ty=='flight'?{fno:fl[1]+' '+fl[2]}:{}})});return days}
const AI_TOOLS=[['itinerary','Generate itinerary ideas'],['import','Import itinerary from text'],['email','Draft client email'],['triage','Triage inbox'],['guide','Destination guide'],['packing','Packing list'],['summary','Trip summary'],['notes','Meeting notes → tasks'],['followups','Suggest follow-up tasks'],['commission','Commission matching'],['agent','Automation agent queue']];
function aiRun(tool,input){const t=aiCtxTrip(),k=cbyid(X.ai.ctxContact),props=[];let say='';
 switch(tool){
 case 'itinerary':{const ideas=DEST_IDEAS[gkey(t.dest)]||DEST_IDEAS.default,lib=X.lib.filter(a=>a.loc&&t.dest&&t.dest.toLowerCase().includes(a.loc.split(',')[0].toLowerCase()));const acts=lib.slice(0,3).map(a=>({type:a.type,title:a.title,desc:a.desc,price:a.price})).concat(ideas.map(i=>({type:i[0],title:i[1],desc:i[2],price:i[3]})));const o=ITX(t.id).opts[0];say=`For ${t.n} (${t.dest||'destination TBD'}), here are ${acts.length} activity ideas drawn from your library and destination notes. Review and approve to add them as a new day.`;props.push(aiProp('acts',`Add ${acts.length} suggested activities to ${t.n}`,'trip:'+t.id,`${o.days.length} days · ${o.days.reduce((s,d)=>s+d.acts.length,0)} activities`,acts.map(a=>`+ [${ACT_TYPES[a.type].l}] ${a.title}${a.price?' ('+mny(a.price)+')':''}`),{trip:t.id,days:[{t:'Suggested experiences',acts}]}));break}
 case 'import':{const days=aiParse(input||'');if(!days.length){say='Paste itinerary text (e.g. “Day 1: Arrive… / Flight BA 123 at 09:40 / Hotel …”) and run again.';break}say=`I found ${days.length} day(s) and ${days.reduce((s,d)=>s+d.acts.length,0)} activities. Each line was classified by keywords (flight numbers, hotel words, meals…).`;props.push(aiProp('acts',`Import ${days.reduce((s,d)=>s+d.acts.length,0)} activities into ${t.n}`,'trip:'+t.id,`${ITX(t.id).opts[0].days.length} days currently`,days.flatMap((d,i)=>[`Day ${i+1}: ${d.t}`,...d.acts.map(a=>`   + [${ACT_TYPES[a.type].l}] ${a.title}`)]),{trip:t.id,days}));break}
 case 'email':{const e=aiEmail(t,k);say='Here’s a draft based on the trip status and your AI tone preference. Approving saves it as a draft in the Demo outbox for your review.';props.push(aiProp('email','Draft: '+e.subj,e.ref,'(no draft)',e.subj+'\n\n'+e.body,e));break}
 case 'triage':{const l=S.mail.map((m,i)=>triage(m,i)).filter(r=>!S.mail[r.i].done);say=`Triaged ${l.length} message(s): `+l.map(r=>`“${S.mail[r.i][2]}” → ${r.cat}${r.t?' (trip: '+r.t.n+')':''}`).join('; ')+'.';l.filter(r=>r.cat!='General').slice(0,3).forEach(r=>props.push(aiProp('task',`Task from email: ${r.fu}`,r.t?'trip:'+r.t.id:r.c?'contact:'+r.c.id:'',`Email “${S.mail[r.i][2]}”`,'+ Task: '+r.fu,{t:r.fu+' — '+S.mail[r.i][2],rt:r.t?'trip':r.c?'contact':'',rid:r.t?r.t.id:r.c?r.c.id:''})));break}
 case 'guide':{const g=X.guides.find(x=>t.dest&&x.dest.split(',')[0]&&t.dest.includes(x.dest.split(',')[0]));const ng=g?null:{id:uid('g'),dest:t.dest||'Destination',title:(t.dest||'Destination').split(',')[0]+' essentials',sec:[['Getting around','Book private transfers for arrival day; use licensed taxis or ride-share in cities.'],['Etiquette','Learn a few local greetings; dress modestly for religious sites.'],['Money','Cards are widely accepted; carry small notes for tips and markets.']]};say=g?`Your library already has “${g.title}”. Approve to attach it to ${t.n}.`:`I drafted a starter guide for ${t.dest}. Approve to save it to the library and attach it.`;props.push(aiProp('guide',`Attach destination guide to ${t.n}`,'trip:'+t.id,ITX(t.id).guide?'Guide attached':'No guide',g?g.title:ng.title+'\n'+ng.sec.map(s=>'• '+s[0]+': '+s[1]).join('\n'),{trip:t.id,gid:g?g.id:'',ng}));break}
 case 'packing':{const base=/Kenya|Mara/.test(t.dest)?X.packing[1]:/Danube|Rhine/.test(t.dest)||(t.sd||'').slice(5,7)>='11'?X.packing[2]:X.packing[0],items=base.items.concat((t.tg||[]).includes('Anniversary')?['Something special for the anniversary dinner']:[]);say=`Packing list for ${t.dest||'your trip'} based on destination, season (${t.sd?MON[dP(t.sd).getUTCMonth()]:'unknown'}) and trip tags.`;props.push(aiProp('pack',`Add ${items.length} packing items to ${t.n}`,'trip:'+t.id,`${ITX(t.id).pack.length} items`,items.map(x=>'+ '+x),{trip:t.id,items}));break}
 case 'summary':{say=aiSummary(t);props.push(aiProp('note','Save summary to trip notes','trip:'+t.id,(S.notes[t.id]||'(empty)').slice(0,80),say,{trip:t.id,note:say}));break}
 case 'notes':{const items=(input||'').split(/\n|\.\s/).map(x=>x.trim()).filter(x=>/(will|need to|follow up|send|book|confirm|call|check|todo|to-do|action)/i.test(x));if(!items.length){say='Paste meeting notes and I’ll pull out action items (lines with “will”, “need to”, “send”, “book”, “confirm”…).';break}say=`Found ${items.length} action item(s).`;props.push(aiProp('tasks',`Create ${items.length} tasks from meeting notes`,'trip:'+t.id,`${tripTasks(t).filter(x=>!x.x).length} open tasks`,items.map(x=>'+ '+x),{tasks:items,trip:t.id}));break}
 case 'followups':{const p=aiFollowups(t);say=`Based on ${t.n}’s status, payments, approvals and bookings, I suggest ${p.payload.tasks.length} follow-up task(s).`;props.push(p);break}
 case 'commission':{const l=X.stmts.flatMap(s=>s.lines.filter(x=>!x.m).map(x=>({s,x}))).map(({s,x})=>({s,x,m:suggestMatch(x)}));if(!l.length){say='All statement lines are matched — nothing to suggest.';break}say=`${l.length} unmatched statement line(s). Suggestions use confirmation number first, then guest name + amount.`;l.filter(z=>z.m).forEach(z=>props.push(aiProp('match',`Match ${z.x.conf} (${mny(z.x.amt)}) → ${z.m.ref}`,'booking:'+z.m.ref,`${z.s.id} line unmatched`,`${z.m.ref} · matched by ${z.m.why}`,{stmt:z.s.id,line:z.x.id,ref:z.m.ref})));if(l.some(z=>!z.m))say+=` ${l.filter(z=>!z.m).length} line(s) have no confident match and should go to Unclaimed.`;break}
 case 'agent':{const n=X.ai.props.filter(p=>p.st=='pending'&&p.src.startsWith('Automation')).length;say=n?`${n} suggestion(s) were prepared by the demo AI agent action in automations. Review them below.`:'No agent suggestions yet. Add a “Run demo AI agent” action to an automation and run it (e.g. the “Inquiry form → triage” rule).';break}}
 X.ai.msgs.push({r:'ai',txt:say,at:nowStamp(),tool});props.forEach(p=>X.ai.props.unshift(p));X.set.aiUsed++;return props}
function aiAsk(){const q=val('aiq2');if(!q)return;X.ai.msgs.push({r:'me',txt:q,at:nowStamp()});const s=q.toLowerCase(),tool=/import|paste/.test(s)?'import':/itinerar|activit|ideas|suggest.*(do|see)/.test(s)?'itinerary':/email|draft|write/.test(s)?'email':/triage|inbox/.test(s)?'triage':/guide/.test(s)?'guide':/pack/.test(s)?'packing':/summar/.test(s)?'summary':/meeting|notes/.test(s)?'notes':/follow|task/.test(s)?'followups':/commission|statement|match/.test(s)?'commission':/agent|automation/.test(s)?'agent':null;if(tool)aiRun(tool,X.ui.aiIn||q);else X.ai.msgs.push({r:'ai',txt:'I can: '+AI_TOOLS.map(t=>t[1].toLowerCase()).join(', ')+'. Try “suggest activities” or “draft an email”.',at:nowStamp()});draw();setTimeout(()=>{const e=$('#aichat');if(e)e.scrollTop=e.scrollHeight},20)}
function aiApply(id,ok){if(ok&&!guard('ai.approve'))return;const p=X.ai.props.find(x=>x.id==id);if(!p||p.st!='pending')return;if(!ok){p.st='rejected';logA(p.rec,'AI suggestion rejected: '+p.title,'ai');draw();return}const P=p.payload;
 if(p.kind=='acts'){const o=ITX(P.trip).opts[0];P.days.forEach(d=>o.days.push({id:uid('day'),t:d.t,acts:d.acts.map(a=>A(a.type,a.title,a.desc||'',{price:a.price||0,time:a.time||'',f:a.f||{}}))}))}
 if(p.kind=='email'){X.outbox.unshift({id:uid('em'),to:P.to||'',ref:P.ref,subj:P.subj,body:P.body,st:'Draft',at:nowStamp(),auto:'AI draft',runAt:''})}
 if(p.kind=='task'){addTask({t:P.t,rt:P.rt,rid:P.rid,due:addD(TODAY(),2),pri:'Medium',src:'AI suggestion'})}
 if(p.kind=='tasks'){P.tasks.forEach(x=>addTask({t:x,rt:P.trip?'trip':'',rid:P.trip||'',due:addD(TODAY(),3),pri:'Medium',src:'AI suggestion'}))}
 if(p.kind=='guide'){if(P.ng)X.guides.push(P.ng);ITX(P.trip).guide=P.gid||P.ng.id}
 if(p.kind=='pack'){const it=ITX(P.trip);P.items.forEach(x=>{if(!it.pack.some(y=>y.t==x))it.pack.push({t:x,x:0})})}
 if(p.kind=='note'){if(P.trip)S.notes[P.trip]=(S.notes[P.trip]?S.notes[P.trip]+'\n\n':'')+'[AI summary '+TODAY()+'] '+P.note}
 if(p.kind=='match'){const st=X.stmts.find(s=>s.id==P.stmt),ln=st&&st.lines.find(l=>l.id==P.line);if(ln)ln.m=P.ref}
 p.st='approved';logA(p.rec,'AI suggestion approved: '+p.title,'ai');toast('Applied to prototype records');draw()}
Pg.ai=()=>{const t=aiCtxTrip(),pend=X.ai.props.filter(p=>p.st=='pending'),done=X.ai.props.filter(p=>p.st!='pending');
 return hd('AI workspace',`<span class="mu" style="font-size:12px">${X.set.aiUsed} demo AI actions this month</span>`,'Deterministic demo assistant grounded in your mock data — every change needs your approval')+DM(AI_NOTE)+
 `<div class="g g21"><div><div class="cd"><header><h2>Context</h2></header><div class="bd g g2 fm"><div><label>Trip</label>${sel('',S.trips.map(x=>[x.id,x.n]),X.ai.ctxTrip,'onchange="X.ai.ctxTrip=this.value;const t=tripById(this.value);if(t&&t.cid)X.ai.ctxContact=t.cid;draw()"')}</div><div><label>Client</label>${sel('',S.cm.filter(c=>c.ty=='Client').map(c=>[c.id,c.f+' '+c.l]),X.ai.ctxContact,'onchange="X.ai.ctxContact=this.value;draw()"')}</div></div></div>
 <div class="cd"><header><h2>Assistant</h2><button class="btn o s" onclick="X.ai.msgs=[];draw()">Clear</button></header><div class="bd"><div class="aichat" id="aichat">${X.ai.msgs.map(m=>`<div class="aim ${m.r}"><div>${esc(m.txt)}</div>${m.r=='ai'?`<span class="mu" style="font-size:10px">${AI_NOTE}</span>`:''}</div>`).join('')||`<p class="mu">Ask something like “suggest activities for this trip”, or pick a tool below. Context: <b>${esc(t.n)}</b>.</p>`}</div><div class="row" style="margin-top:8px"><input id="aiq2" placeholder="Ask the demo assistant…" style="flex:1" onkeydown="if(event.key=='Enter')aiAsk()"><button class="btn" onclick="aiAsk()">Send</button></div><div class="row" style="margin-top:8px">${AI_TOOLS.map(x=>`<button class="btn o s" onclick="X.ai.msgs.push({r:'me',txt:'${x[1]}',at:nowStamp()});aiRun('${x[0]}',X.ui.aiIn||'');draw()">${x[1]}</button>`).join('')}</div><label class="mu" style="font-size:12px;display:block;margin-top:10px">Paste text for “Import itinerary” or “Meeting notes”</label><textarea rows="4" placeholder="Day 1: Arrive in Lisbon&#10;Flight TP 204 arrives 09:40&#10;Check in at Palácio Belmonte&#10;Dinner at Belcanto 20:00" oninput="X.ui.aiIn=this.value">${esc(X.ui.aiIn||'')}</textarea></div></div></div>
 <div>${cd(`Proposed changes (${pend.length})`,pend.map(p=>`<div class="aiprop"><b>${esc(p.title)}</b><div class="mu" style="font-size:12px">${p.rec?`<a class="lk" onclick="openRef('${p.rec}')">${esc(refName(p.rec))}</a> · `:''}${esc(p.src)} · ${esc(p.at)}</div><div class="g g2" style="margin:6px 0"><div><span class="mu" style="font-size:11px">Before</span><div class="pv">${esc(p.before)}</div></div><div><span class="mu" style="font-size:11px">After</span><div class="pv">${esc(Array.isArray(p.after)?p.after.join('\n'):p.after)}</div></div></div><div class="row"><button class="btn s" onclick="aiApply('${p.id}',1)" ${dis('ai.approve')}>Approve</button><button class="btn o s" onclick="aiApply('${p.id}',0)">Reject</button></div></div>`).join('')||'<p class="mu">Nothing waiting for review.</p>')}${cd('AI activity log',done.slice(0,10).map(p=>`<div class="ts" style="font-size:12px">${pill(p.st=='approved'?'Approved':'Rejected',p.st=='approved'?'Active':'Cancelled')}<span>${esc(p.title)}<div class="mu">${esc(p.at)}</div></span></div>`).join('')||'<p class="mu">No decisions yet.</p>')}</div></div>`};

