const rpF=()=>X.ui.rpf||(X.ui.rpf={from:'2026-01-01',to:'2027-12-31',adv:'',st:'',rep:'Trips by status'});
const REPORTS=['Trips by status','Trips by destination','Trips per month','Upcoming departures','Bookings by supplier','Bookings by advisor','Commissions','Revenue by month','Task completion','Automation executions','Workflow effectiveness','Client inquiries & conversion','Group registrations','Payment status','Advisor performance'];
function rpData(){const f=rpF(),T=S.trips.filter(t=>t.type!='sub'&&(!f.adv||t.ow==f.adv)&&(!f.st||t.st==f.st)&&(!t.sd||(t.sd>=f.from&&t.sd<=f.to))),B=X.bookings.filter(b=>(!f.adv||b.agent==f.adv)&&b.date>=f.from&&b.date<=f.to),cnt=(arr,fn)=>{const o={};arr.forEach(x=>{const k=fn(x);o[k]=(o[k]||0)+1});return o},sm=(arr,fn,vf)=>{const o={};arr.forEach(x=>{const k=fn(x);o[k]=(o[k]||0)+vf(x)});return o};
 switch(f.rep){
 case 'Trips by status':{const o=cnt(T,t=>t.st);return {h:['Status','Trips'],r:X.statuses.filter(s=>o[s]).map(s=>[s,o[s]]),chart:'hb'}}
 case 'Trips by destination':{const o=cnt(T,t=>(t.dest||'TBD').split(',').pop().trim());return {h:['Country / region','Trips'],r:Object.entries(o).sort((a,b)=>b[1]-a[1]),chart:'hb'}}
 case 'Trips per month':{const o=cnt(T.filter(t=>t.sd),t=>t.sd.slice(0,7));return {h:['Month','Trips'],r:Object.keys(o).sort().map(k=>[MON[+k.slice(5)-1]+' '+k.slice(2,4),o[k]]),chart:'bars'}}
 case 'Upcoming departures':return {h:['Departs','Trip','Client','Status','Days away'],r:T.filter(t=>t.sd&&t.sd>=TODAY()).sort((a,b)=>a.sd<b.sd?-1:1).map(t=>[fd(t.sd),t.n,t.c,t.st,dDiff(TODAY(),t.sd)])};
 case 'Bookings by supplier':{const o=sm(B.filter(b=>!b.cxl),b=>b.supplier,b=>b.amt);return {h:['Supplier','Volume (USD)'],r:Object.entries(o).sort((a,b)=>b[1]-a[1]).map(x=>[x[0],Math.round(x[1])]),chart:'hb'}}
 case 'Bookings by advisor':{const o=sm(B.filter(b=>!b.cxl),b=>b.agent,b=>b.amt);return {h:['Advisor','Volume (USD)'],r:Object.entries(o).map(x=>[x[0],Math.round(x[1])]),chart:'hb'}}
 case 'Commissions':{const C=X.comm.filter(c=>B.some(b=>b.ref==c.bk));return {h:['Measure','USD'],r:[['Expected',Math.round(sum(C.filter(c=>c.st!='Cancelled'),c=>c.exp))],['Received',Math.round(sum(C,c=>c.rec))],['Outstanding',Math.round(sum(C.filter(c=>!['Cancelled','Paid out'].includes(c.st)),c=>Math.max(0,c.exp-c.rec)))],['Paid out to agents',Math.round(sum(X.payouts.filter(p=>p.st=='Paid'),p=>p.net))]],chart:'hb'}}
 case 'Revenue by month':{const o=sm(B.filter(b=>!b.cxl),b=>b.date.slice(0,7),b=>b.amt);return {h:['Month','Booked revenue (USD)'],r:Object.keys(o).sort().map(k=>[MON[+k.slice(5)-1]+' '+k.slice(2,4),Math.round(o[k]/100)/10+'k']),raw:Object.keys(o).sort().map(k=>Math.round(o[k]/100)/10),chart:'bars'}}
 case 'Task completion':{const U=S.users.map(u=>u[0]).filter(u=>!f.adv||u==f.adv);return {h:['Assignee','Completed','Open','Overdue','Completion %'],r:U.map(u=>{const l=S.tasks.filter(k=>k.asg==u);return [u,l.filter(k=>k.x).length,l.filter(k=>!k.x).length,l.filter(k=>!k.x&&k.due&&k.due<TODAY()).length,l.length?Math.round(l.filter(k=>k.x).length/l.length*100):0]}),chartCol:4}}
 case 'Automation executions':{const o=cnt(X.runs,r=>r.res);return {h:['Result','Runs'],r:[['success',o.success||0],['skipped',o.skipped||0],['failed',o.failed||0]],chart:'hb'}}
 case 'Workflow effectiveness':return {h:['Workflow','Applied to','Tasks created','Tasks completed','Completion %'],r:X.wfs.map(w=>{const ks=S.tasks.filter(k=>(k.src||'')=='Workflow: '+w.n),ap=Object.keys(X.wfApplied).filter(k=>k.startsWith(w.id+'|')).length;return [w.n,ap,ks.length,ks.filter(k=>k.x).length,ks.length?Math.round(ks.filter(k=>k.x).length/ks.length*100):0]}).filter(r=>r[1]),chartCol:1};
 case 'Client inquiries & conversion':{const all=S.trips.filter(t=>t.type!='sub'),conv=all.filter(t=>['Approved','Booked','Traveling','Traveled'].includes(t.st)).length,src=cnt(S.cm.filter(c=>c.ty=='Client'||c.ty=='Lead'),c=>c.src||'Unknown');return {h:['Measure','Value'],r:[['Total trips (all time)',all.length],['Open inquiries',all.filter(t=>t.st=='Inquiry').length],['Converted (approved or later)',conv],['Lead conversion rate',Math.round(conv/Math.max(1,all.length)*100)+'%'],...Object.entries(src).map(x=>['Lead source: '+x[0],x[1]])]}}
 case 'Group registrations':return {h:['Group trip','Registrations','Travelers','Seats','Collected (USD)'],r:S.trips.filter(t=>t.type=='group').map(g=>[g.n,groupSubs(g).length,groupSeats(g),g.grp.seats,Math.round(sum(groupSubs(g).flatMap(s=>tripPays(s.id)),p=>p.paid))]),chartCol:2};
 case 'Payment status':{const o=cnt(X.pay.filter(p=>p.st!='Void'),payState);return {h:['Status','Payments'],r:Object.entries(o),chart:'hb'}}
 case 'Advisor performance':return {h:['Advisor','Trips','Booked volume','Expected commission','Agent share'],r:S.users.map(u=>u[0]).filter(u=>!f.adv||u==f.adv).map(u=>{const bv=sum(B.filter(b=>b.agent==u&&!b.cxl),b=>b.amt),ce=sum(X.comm.filter(c=>c.agent==u&&c.st!='Cancelled'),c=>c.exp);return [u,T.filter(t=>t.ow==u).length,Math.round(bv),Math.round(ce),Math.round(ce*(X.splits[u]||0)/100)]}),chartCol:2}}
 return {h:[],r:[]}}
