function stSet(p,v){const ks=p.split('.');let o=X.set;while(ks.length>1)o=o[ks.shift()];o[ks[0]]=v;logA('','Setting updated: '+p,'info');if(p=='profile.name'){}draw()}
function stLogo(inp){const f=inp.files[0];if(!f)return;if(f.size>400000)return toast('Logo too large for the local demo (max ~400 KB)');const r=new FileReader();r.onload=()=>{X.set.logo=r.result;draw()};r.readAsDataURL(f)}
function applyBrand(){document.documentElement.style.setProperty('--gd',X.set.brand||'#c19a3b')}
function stRen(i,v){v=v.trim();if(!v||X.statuses.includes(v))return draw();const old=X.statuses[i];X.statuses[i]=v;S.trips.forEach(t=>{if(t.st==old)t.st=v});draw()}
function stMv(i,d){const a=X.statuses;if(!a[i+d])return;[a[i],a[i+d]]=[a[i+d],a[i]];draw()}
function stDelS(i){const s=X.statuses[i],n=S.trips.filter(t=>t.st==s).length;if(n)return toast(`${n} trip(s) use “${s}” — move them first`);X.statuses.splice(i,1);draw()}
function stAddS(){dlg('New trip status','<label>Name</label><input id="a1" placeholder="e.g. Deposit pending">','Add',()=>{const v=val('a1');if(!v||X.statuses.includes(v))return err('Enter a new, unique name.');X.statuses.splice(X.statuses.indexOf('Booked'),0,v);STATUS_LEGACY[v]='Planning';cl();draw()})}

