function callTo(num,cid,trip){if(!num){toast('No phone number on file — add one to the contact first');return}if(!can('calls.use')){toast('Your role does not use the softphone');return}if(X.phone.call){toast('Finish the current call first');spOpen();return}X.phone.num=num;X.phone.pre=cid||'';X.phone.preTrip=trip||'';spOpen()}
const callBtn=(num,cid,trip,small)=>num?`<button class="btn o ${small?'s ':''}cbtn" aria-label="Call ${esc(num)}" title="Call ${esc(num)}" onclick="event.stopPropagation();callTo('${esc(num)}','${cid||''}','${trip||''}')">${ic('phone',small?12:14)}${small?'':' Call'}</button>`:'';
function phNewContact(num0,callId){const c=X.phone.call,num=num0||(c?c.num:'');dlg('Create contact from number',`<div class="g g2"><div><label>First name</label><input id="pn1"></div><div><label>Last name</label><input id="pn2"></div></div><label>Phone</label><input id="pn3" value="${esc(num)}"><label>Email</label><input id="pn4" type="email"><label>Type</label>${sel('pn5',['Lead','Client'],'Lead')}`,'Create contact',()=>{if(!val('pn1'))return err('Enter a first name.');const k={id:uid('c'),f:val('pn1'),l:val('pn2'),e:val('pn4'),ph:val('pn3'),t:'',ti:'',b:'',g:[],ty:val('pn5'),mk:'Not opted',ann:'',pp:'',hh:[],prefs:{},loy:[],src:'Phone call',created:TODAY()};S.cm.unshift(k);
 const live=X.phone.call;if(live&&normPh(live.num)==normPh(k.ph)){live.cid=k.id;live.name=k.f+' '+k.l}const rec=callId?X.calls.find(x=>x.id==callId):null;if(rec){rec.cid=k.id;rec.name=k.f+' '+k.l}
 logA('contact:'+k.id,'Contact created from phone number '+k.ph,'call');cl();fire('contact_created','contact',k.id);spR();toast('Contact created');if(callId)callSummary(callId);else draw()})}
function phTransfer(){const ag=Object.keys(X.phone.agents).filter(a=>a!=X.me);dlg('Transfer call',`<p class="mu">Choose a teammate. Their status is simulated.</p>${ag.map(a=>`<label class="ck" style="font-size:14px"><input type="radio" name="trf" value="${esc(a)}" ${X.phone.agents[a]=='Offline'?'disabled':''}><span class="stdot" style="background:${STCOL[X.phone.agents[a]]}"></span>${esc(a)} <span class="mu">· ${X.phone.agents[a]}</span></label>`).join('')}`,'Transfer',()=>{const v=(document.querySelector('input[name=trf]:checked')||{}).value;if(!v)return err('Choose who to transfer to.');cl();Telephony.transfer(v);toast('Call transferred to '+v+' (simulated)')})}
function phConf(){const ag=Object.keys(X.phone.agents).filter(a=>a!=X.me&&X.phone.agents[a]!='Offline');dlg('Add participant',`<label>Teammate</label>${sel('cf1',[['','—'],...ag],'')}<label>Or external number</label><input id="cf2" placeholder="+1 (555) 010-0000">`,'Add to call',()=>{const n=val('cf1')||val('cf2');if(!n)return err('Choose a teammate or enter a number.');const c=X.phone.call;if(!c)return cl();const p={n,st:'Ringing'};c.conf.push(p);cl();spR();phLater(()=>{p.st='Connected';spR()},1200)})}

/* ---------- call summary (disposition) ---------- */
const DISPS=['Interested','Requested Quote','Follow-Up Required','Booked','Not Interested','No Answer','Wrong Number','Resolved','Other'];
function callSummary(id){const r=X.calls.find(x=>x.id==id);if(!r)return;const k=r.cid?cbyid(r.cid):null,trips=k?cTrips(k):[];
 dlgW('Call summary',`<div class="row sp" style="margin-bottom:6px"><span>${ic(r.dir=='Inbound'?'phoneIn':'phoneOut',14)} ${r.dir} · ${pill(r.st,r.st=='Answered'?'Active':['Missed','Declined','Failed','Busy'].includes(r.st)?'Overdue':'Pending')}</span><span class="mu">${fd(r.date)} ${r.start} · ${fmtDur(r.dur)}</span></div><div class="fm"><div class="g g2"><div><label>Contact</label>${k?`<div><a class="lk" onclick="cl();S.cc='${k.id}';go('client')">${esc(k.f+' '+k.l)}</a> <span class="mu">${esc(r.num)}</span></div>`:`<div>${esc(r.num)} <button class="btn o s" onclick="phNewContact('${esc(r.num)}','${r.id}')">Create contact</button></div>`}</div><div><label>Duration</label><input value="${fmtDur(r.dur)}" disabled></div><div><label>Call result</label>${sel('cs1',[['','— Choose —'],...DISPS],r.disp||(r.st=='Answered'?'':'No Answer'))}</div><div><label>Related trip</label>${sel('cs2',[['','— None —'],...trips.map(t=>[t.id,t.n]),...S.trips.filter(t=>!trips.includes(t)).map(t=>[t.id,t.n])],r.trip)}</div></div><label>Notes</label><textarea id="cs3" rows="3">${esc(r.notes)}</textarea><div class="g g2"><div><label class="ck" style="font-size:13px;margin-top:14px"><input type="checkbox" id="cs4" ${r.fu?'checked':''}> Follow-up required</label></div><div><label>Follow-up date</label><input id="cs5" type="date" value="${r.fu?r.fu.date:addD(TODAY(),2)}"></div><div><label>Assigned advisor</label>${sel('cs6',S.users.map(u=>u[0]),r.agent)}</div></div></div>`,'Save summary',()=>{const disp=val('cs1'),prev=r.disp,fu=val('cs4'),agentPrev=r.agent;if(fu&&!val('cs5'))return err('Choose a follow-up date.');r.disp=disp;r.trip=val('cs2');r.notes=val('cs3');r.agent=val('cs6');r.fu=fu?{date:val('cs5'),agent:val('cs6')}:null;
  logA(r.cid?'contact:'+r.cid:'',`Call summary saved — ${disp||'no result'}${r.notes?': '+r.notes.slice(0,60):''}`,'call');if(r.trip)logA('trip:'+r.trip,'Call summary: '+(disp||'no result'),'call');cl();
  if(disp&&disp!=prev)phFire('call_disposition',r);if(fu)phFire('followup_required',r);if(r.agent!=agentPrev)phFire('call_assigned',r);toast('Call saved');draw()},640)}

/* ---------- pages ---------- */
const callPill=s=>pill(s,s=='Answered'?'Active':['Missed','Declined','Failed','Busy'].includes(s)?'Overdue':s=='Voicemail'?'Pending':'');
Pg.calls=()=>{const k=tb('cl',['Dialer','Directory']),P=X.phone;let b='';
 if(k=='Dialer')b=`<div class="g g2"><div class="cd"><header><h2>Dialer</h2><span class="mu" style="font-size:12px">Calls open in the softphone panel</span></header><div class="bd pgdial">${spDialer('pg')}</div></div><div>${cd('Team availability',Object.entries(P.agents).map(([a,s])=>`<div class="ts" style="align-items:center"><span class="stdot" style="background:${STCOL[s]}"></span><span style="flex:1">${esc(a)}${a==X.me?' (you)':''}</span><span class="mu">${s}</span></div>`).join(''))}${cd('Business lines',X.lines.map(l=>`<div class="row sp ts"><span>${esc(l.n)}</span><span class="mu">${esc(l.num)}</span></div>`).join(''))}${cd('Recent calls',X.calls.slice(0,5).map(phRow).join(''),`<button class="btn o s" onclick="go('callhist')">All calls</button>`)}</div></div>`;
 if(k=='Directory'){const q=(X.ui.pdq||'').toLowerCase(),l=S.cm.filter(c=>c.ph&&(c.f+' '+c.l+' '+c.ph).toLowerCase().includes(q));b=`<div class="row" style="margin-bottom:10px">${searchBox('pdq',X.ui.pdq,"X.ui.pdq=this.value;clearTimeout(window._pq);window._pq=setTimeout(()=>{draw();const e=$('#pdq');e.focus();e.setSelectionRange(e.value.length,e.value.length)},250)",'Search contacts with phone numbers')}</div><div class="cd"><div class="tw"><table class="t2"><thead><tr><th>Contact</th><th>Phone</th><th>Type</th><th>Next trip</th><th>Last call</th><th></th></tr></thead><tbody>${l.map(c=>{const lc=X.calls.find(x=>x.cid==c.id),t=nextTripFor(c.id);return `<tr><td><a class="lk" onclick="S.cc='${c.id}';go('client')">${esc(c.f+' '+c.l)}</a></td><td>${esc(c.ph)}</td><td>${esc(c.ty||'')}</td><td>${t?esc(t.n):'—'}</td><td>${lc?fd(lc.date)+' · '+lc.st:'—'}</td><td>${callBtn(c.ph,c.id,t?t.id:'',1)}</td></tr>`}).join('')}</tbody></table></div></div>`}
 return hd('Calls',`<button class="btn o" onclick="go('callset')">${ic('sliders')} Call settings</button><button class="btn" onclick="spOpen()">${ic('phone')} Open softphone</button>`,'CRM-integrated softphone — simulated until a telephony provider is connected')+DM('Simulated mode: no real calls are placed or received, and no audio is captured.')+tabs('cl',['Dialer','Directory'])+b};
function phRow(r){return `<div class="ts" style="cursor:pointer;align-items:center" onclick="callDetail('${r.id}')">${ic(r.dir=='Inbound'?(r.st=='Missed'?'phoneMiss':'phoneIn'):'phoneOut',15)}<span style="flex:1">${esc(r.cid?refName('contact:'+r.cid):r.num)}<div class="mu" style="font-size:12px">${fd(r.date)} ${r.start} · ${fmtDur(r.dur)}</div></span>${callPill(r.st)}</div>`}
const chF=()=>X.ui.chf||(X.ui.chf={q:'',dir:'',st:'',ag:'',from:'2026-10-01',to:'2026-12-31'});
const chList=()=>{const f=chF(),k=tb('ch',['Recent','Missed','All']);return X.calls.filter(r=>(k!='Missed'||['Missed','Declined','Voicemail'].includes(r.st))&&(!f.dir||r.dir==f.dir)&&(!f.st||r.st==f.st)&&(!f.ag||r.agent==f.ag)&&r.date>=f.from&&r.date<=f.to&&((r.cid?refName('contact:'+r.cid):r.name)+' '+r.num+' '+r.notes+' '+(r.disp||'')).toLowerCase().includes(f.q.toLowerCase())).slice(0,k=='Recent'?25:500)};
Pg.callhist=()=>{const f=chF(),l=chList(),miss=X.calls.filter(r=>['Missed','Declined','Voicemail'].includes(r.st)).length;
 return hd('Call history',`<button class="btn o" onclick="dlFile('call-history-demo.csv',csv(['Contact','Phone','Direction','Status','Agent','Date','Start','Duration (s)','Trip','Disposition','Notes','Recording'],chList().map(r=>[r.cid?refName('contact:'+r.cid):r.name,r.num,r.dir,r.st,r.agent,r.date,r.start,r.dur,r.trip?(tripById(r.trip)||{}).n:'',r.disp,r.notes,r.rec])))">${ic('dl')} Export CSV</button><button class="btn" onclick="spOpen()">${ic('phone')} New call</button>`)+
 `<div class="tabs">${['Recent','Missed','All'].map(x=>`<button class="${tb('ch',['Recent','Missed','All'])==x?'on':''}" onclick="S.tab.ch='${x}';draw()">${x}${x=='Missed'?`<span class="cnt">${miss}</span>`:''}</button>`).join('')}</div>`+
 `<div class="row" style="margin-bottom:12px">${searchBox('chq',f.q,"X.ui.chf.q=this.value;clearTimeout(window._cq3);window._cq3=setTimeout(()=>{draw();const e=$('#chq');e.focus();e.setSelectionRange(e.value.length,e.value.length)},250)",'Search name, number, notes')}${sel('chd',[['','Both directions'],'Inbound','Outbound'],f.dir,'style="width:auto" aria-label="Direction" onchange="X.ui.chf.dir=this.value;draw()"')}${sel('chs',[['','All statuses'],'Answered','Missed','Declined','Busy','Failed','Voicemail'],f.st,'style="width:auto" aria-label="Status" onchange="X.ui.chf.st=this.value;draw()"')}${sel('cha',[['','All agents'],...S.users.map(u=>u[0])],f.ag,'style="width:auto" aria-label="Agent" onchange="X.ui.chf.ag=this.value;draw()"')}<label class="mu" style="font-size:12px">From</label><input type="date" value="${f.from}" style="width:auto" aria-label="From date" onchange="X.ui.chf.from=this.value;draw()"><label class="mu" style="font-size:12px">To</label><input type="date" value="${f.to}" style="width:auto" aria-label="To date" onchange="X.ui.chf.to=this.value;draw()"></div>`+
 (l.length?`<div class="cd"><div class="tw"><table class="t2"><thead><tr><th>Contact</th><th>Phone number</th><th>Direction</th><th>Status</th><th>Agent</th><th>Date</th><th>Start</th><th>Duration</th><th>Trip</th><th>Notes</th><th>Recording</th><th></th></tr></thead><tbody>${l.map(r=>`<tr class="c" onclick="callDetail('${r.id}')"><td><span class="lk">${esc(r.cid?refName('contact:'+r.cid):r.name)}</span>${r.disp?`<div class="mu" style="font-size:11px">${esc(r.disp)}</div>`:''}</td><td>${esc(r.num)}</td><td>${ic(r.dir=='Inbound'?'phoneIn':'phoneOut',13)} ${r.dir}</td><td>${callPill(r.st)}</td><td>${esc(r.agent)}</td><td>${fd(r.date)}</td><td>${r.start}</td><td>${fmtDur(r.dur)}</td><td>${r.trip?esc((tripById(r.trip)||{}).n||''):'—'}</td><td style="max-width:200px;overflow:hidden;text-overflow:ellipsis">${esc(r.notes||'')}</td><td>${r.rec.startsWith('Recorded')?ic('rec',13)+' Recorded':'<span class="mu">None</span>'}</td><td>${callBtn(r.num,r.cid,r.trip,1)}</td></tr>`).join('')}</tbody></table></div></div>`:emp('phone','No calls match','Adjust the filters.'))};
function callDetail(id){const r=X.calls.find(x=>x.id==id);if(!r)return;dlgW('Call details',`<div class="g g2">${[['Contact',r.cid?`<a class="lk" onclick="cl();S.cc='${r.cid}';go('client')">${esc(refName('contact:'+r.cid))}</a>`:esc(r.name)+` <button class="btn o s" onclick="phNewContact('${esc(r.num)}','${r.id}')">Create contact</button>`],['Phone',esc(r.num)],['Direction',r.dir],['Status',callPill(r.st)],['Agent',esc(r.agent)],['Line',esc((X.lines.find(l=>l.id==r.line)||{n:r.line}).n)],['When',fd(r.date)+' '+r.start],['Duration',fmtDur(r.dur)],['Trip',r.trip?`<a class="lk" onclick="cl();S.cur='${r.trip}';go('trip')">${esc((tripById(r.trip)||{}).n||'')}</a>`:'—'],['Disposition',esc(r.disp||'—')],['Follow-up',r.fu?fd(r.fu.date)+' · '+esc(r.fu.agent):'—'],['Recording',esc(r.rec)]].map(x=>`<div><span class="mu" style="font-size:12px">${x[0]}</span><div>${x[1]}</div></div>`).join('')}</div>${r.notes?`<p style="margin-top:10px;white-space:pre-wrap">${esc(r.notes)}</p>`:''}<div class="row" style="margin-top:12px">${callBtn(r.num,r.cid,r.trip)}<button class="btn o" onclick="callSummary('${r.id}')">${ic('edit',14)} Edit notes & disposition</button><button class="btn o" onclick="cl();tkNew({t:'Follow up call with ${esc(r.cid?refName('contact:'+r.cid):r.num).replace(/'/g,'')}',rt:'${r.cid?'contact':''}',rid:'${r.cid||''}'})">${ic('check',14)} Assign follow-up</button></div>`,null,null,640)}
Pg.voicemail=()=>{const k=tb('vmk',['Inbox','Archived']),l=X.vms.filter(v=>k=='Archived'?v.arch:!v.arch);
 return hd('Voicemail',`<button class="btn o" onclick="S.tab.cs='Voicemail';go('callset')">Voicemail settings</button>`,'Simulated voicemail — transcripts are demo text; no caller was recorded')+tabs('vmk',['Inbox','Archived'])+(l.length?l.map(v=>{const r=X.calls.find(x=>x.id==v.callId)||{};const pl=X.ui.play&&X.ui.play.id==v.id;return `<div class="cd vmc ${v.read?'':'unread'}"><div class="bd"><div class="row sp"><div class="row">${v.read?'':'<span class="stdot" style="background:var(--gd)"></span>'}<b>${esc(r.cid?refName('contact:'+r.cid):r.num)}</b><span class="mu">${esc(r.num||'')}</span></div><span class="mu" style="font-size:12px">${fd(r.date)} ${r.start||''} · ${fmtDur(v.dur)} · ${esc(r.agent||'')}</span></div>${player(v.id,v.dur)}<p class="vmt">${esc(v.tr)}</p><div class="row"><button class="btn o s" onclick="vmMark('${v.id}')">${v.read?'Mark unread':'Mark read'}</button>${callBtn(r.num,r.cid,r.trip,0)}<button class="btn o s" onclick="tkNew({t:'Return voicemail from ${esc(r.cid?refName('contact:'+r.cid):r.num).replace(/'/g,'')}',rt:'${r.cid?'contact':''}',rid:'${r.cid||''}'})">Create task</button>${r.cid?`<button class="btn o s" onclick="S.cc='${r.cid}';go('client')">Open contact</button>`:`<button class="btn o s" onclick="phNewContact('${esc(r.num)}')">Create contact</button>`}<button class="btn o s" onclick="X.vms.find(x=>x.id=='${v.id}').arch=${v.arch?0:1};draw()">${v.arch?'Restore':'Archive'}</button><button class="btn o s" onclick="X.vms=X.vms.filter(x=>x.id!='${v.id}');logA('','Voicemail deleted','call');draw()">Delete</button></div></div></div>`}).join(''):emp('vm','No voicemails','Messages left on your lines appear here.'))};
function vmMark(id){const v=X.vms.find(x=>x.id==id);v.read=v.read?0:1;draw()}
function player(id,dur){const p=X.ui.play&&X.ui.play.id==id?X.ui.play:null,pos=p?p.pos:0;return `<div class="player"><button class="ib" aria-label="${p&&p.on?'Pause':'Play'} (simulated)" onclick="plToggle('${id}',${dur})">${ic(p&&p.on?'pause':'play',16)}</button><div class="pbar"><i id="pb_${id}" style="width:${dur?pos/dur*100:0}%"></i></div><span class="mu" id="pt_${id}" style="font-size:12px">${fmtDur(pos)} / ${fmtDur(dur)}</span><span class="demo-tag">No audio</span></div>`}
function plToggle(id,dur){let p=X.ui.play;if(!p||p.id!=id){clearInterval(PHT.pl);p=X.ui.play={id,pos:0,on:0}}p.on=!p.on;if(p.on){if(id.startsWith('vm')){const v=X.vms.find(x=>x.id==id);if(v)v.read=1}PHT.pl=setInterval(()=>{p.pos=Math.min(dur,p.pos+1);const b=document.getElementById('pb_'+id),t=document.getElementById('pt_'+id);if(b)b.style.width=p.pos/dur*100+'%';if(t)t.textContent=fmtDur(p.pos)+' / '+fmtDur(dur);if(p.pos>=dur){p.on=0;clearInterval(PHT.pl)}},250)}else clearInterval(PHT.pl);draw()}
Pg.recordings=()=>{const l=X.calls.filter(r=>r.rec.startsWith('Recorded')),ok=can('calls.recordings');
 return hd('Call recordings',``,'Demo recordings only — the prototype never captures audio')+`<div class="info"><div><b>Access restriction preview</b><p>Recordings are visible to Company Owner, Agency Administrator and Team Supervisor. Your demo role: <b>${esc(roleLabel(X.role))}</b> — ${ok?'access granted':'restricted'}. Production must add recording consent, call disclosures and retention rules (see SOFTPHONE_FEATURE_SPEC.md).</p></div></div>`+
 (l.length?l.map(r=>`<div class="cd"><header><h2>${ic(r.dir=='Inbound'?'phoneIn':'phoneOut',14)} ${esc(r.cid?refName('contact:'+r.cid):r.num)} · ${fd(r.date)} ${r.start}</h2><div class="row">${pill(r.rec)}<span class="mu">${fmtDur(r.dur)}</span></div></header><div class="bd">${ok?`${player(r.id,r.dur)}<label class="mu" style="font-size:12px">Transcript preview</label><div class="emv" style="white-space:pre-wrap">${esc(r.tr||'No transcript')}</div><div class="fm"><label>Notes</label><textarea rows="2" onchange="X.calls.find(x=>x.id=='${r.id}').notes=this.value">${esc(r.notes)}</textarea></div><div class="row" style="margin-top:8px"><button class="btn o s" onclick="callDetail('${r.id}')">Call details</button><button class="btn o s" onclick="dlFile('recording-${r.id}-transcript-demo.txt',X.calls.find(x=>x.id=='${r.id}').tr||'','text/plain')">${ic('dl',13)} Download demo transcript</button><button class="btn o s" onclick="recDel('${r.id}')">Delete recording</button></div>`:`<p class="mu">${ic('lock',14)} Restricted for your role.</p>`}</div></div>`).join(''):emp('rec','No recordings',''))};
function recDel(id){if(!can('calls.recordings'))return guard('calls.recordings');dlg('Delete recording','<p>Delete this demo recording and transcript? The call record stays.</p>','Delete',()=>{const r=X.calls.find(x=>x.id==id);r.rec='Deleted';r.tr='';logA(r.cid?'contact:'+r.cid:'','Call recording deleted','call');cl();draw()})}
const caF=()=>X.ui.caf||(X.ui.caf={from:'2026-10-01',to:'2026-12-31',ag:'',dir:''});
function callStats(){const f=caF(),L=X.calls.filter(r=>r.date>=f.from&&r.date<=f.to&&(!f.ag||r.agent==f.ag)&&(!f.dir||r.dir==f.dir)),ans=L.filter(r=>r.st=='Answered'),inbA=ans.filter(r=>r.dir=='Inbound'&&r.resp),cnt=(a,fn)=>{const o={};a.forEach(x=>{const k=fn(x);if(k)o[k]=(o[k]||0)+1});return o};
 return {L,total:L.length,inb:L.filter(r=>r.dir=='Inbound').length,out:L.filter(r=>r.dir=='Outbound').length,ans:ans.length,miss:L.filter(r=>['Missed','Declined','Voicemail'].includes(r.st)).length,avgDur:ans.length?Math.round(sum(ans,r=>r.dur)/ans.length):0,avgResp:inbA.length?Math.round(sum(inbA,r=>r.resp)/inbA.length):0,perAg:cnt(L,r=>r.agent),disp:cnt(L,r=>r.disp),fu:L.filter(r=>r.fu).length+S.tasks.filter(k=>/^Call back|callback|Return (missed call|voicemail)/i.test(k.t)).length,leads:L.filter(r=>r.disp=='Requested Quote'||r.disp=='Interested').length+S.cm.filter(c=>c.src=='Phone call'&&c.created>=f.from&&c.created<=f.to).length,booked:L.filter(r=>r.disp=='Booked'||(r.trip&&X.bookings.some(b=>b.tripId==r.trip&&!b.cxl))).length}}
