const EMAP={'\u{2708}':'plane','\u{1f3e8}':'bld','\u{1f6f3}':'ship','\u{1f686}':'train','\u{1f697}':'car','\u{1f39f}':'tag','\u{1f9ed}':'globe','\u{1f37d}':'dining','\u{2600}':'sun','\u{1f6e1}':'shield','\u{2726}':'star','\u{1f3f0}':'map','\u{1f34b}':'map','\u{1f992}':'map','\u{1f338}':'map','\u{1f3d4}':'map','\u{1f384}':'map','\u{2611}':'check','\u{26a1}':'bolt','\u{26d4}':'no','\u{2705}':'ok','\u{2713}':'tick','\u{2715}':'x','\u{2717}':'x','\u{1f4c5}':'cal','\u{25b6}':'play','\u{2605}':'star','\u{2610}':'sq','\u{26a0}':'warn','\u{2709}':'mail','\u{270f}':'edit','\u{1f310}':'globe','\u{1f441}':'eye','\u{1f464}':'user','\u{1f465}':'users','\u{1f4ac}':'chat','\u{1f4c4}':'file','\u{1f4cb}':'clip','\u{1f4cd}':'pin','\u{1f4ce}':'clip2','\u{1f4da}':'book','\u{1f4dd}':'edit','\u{1f4e4}':'send','\u{1f4e5}':'inbox','\u{1f501}':'refresh','\u{1f512}':'lock','\u{1f552}':'clock','\u{1f5bc}':'image','\u{1f382}':'gift','\u{1f3e0}':'home','\u{1f48d}':'heart','\u{1f6c2}':'card','\u{23f0}':'clock','\u{1f377}':'wine'};
const EMO_RE=/(\p{Extended_Pictographic}|[\u{2713}\u{2717}\u{2715}\u{2610}\u{2605}\u{2726}])\uFE0F?/gu;
function deEmoji(root){if(!root)return;const fix=t=>t.replace(EMO_RE,'').replace(/\s{2,}/g,' ');
 const one=n=>{const p=n.parentNode;if(!p||!EMO_RE.test(n.nodeValue)){EMO_RE.lastIndex=0;return}EMO_RE.lastIndex=0;const tag=p.nodeName;if(/SCRIPT|STYLE/.test(tag))return;if(/OPTION|TEXTAREA|TITLE/.test(tag)){n.nodeValue=fix(n.nodeValue);return}
  const f=document.createDocumentFragment();let last=0;n.nodeValue.replace(EMO_RE,(m,e,i)=>{f.append(n.nodeValue.slice(last,i));const k=EMAP[e];if(k&&IC[k]){const s=document.createElement('span');s.className='ei';s.setAttribute('aria-hidden','true');s.innerHTML=ic(k,e=='\u{2713}'||e=='\u{2715}'||e=='\u{2717}'?12:14);f.append(s)}last=i+m.length;return m});f.append(n.nodeValue.slice(last));p.replaceChild(f,n)};
 if(root.nodeType==3){one(root);return}if(root.nodeType!=1)return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),L=[];while(w.nextNode())L.push(w.currentNode);L.forEach(one);
 [root,...root.querySelectorAll('[title],[aria-label],[placeholder]')].forEach(e=>{['title','aria-label','placeholder'].forEach(a=>{const v=e.getAttribute&&e.getAttribute(a);if(v&&EMO_RE.test(v)){EMO_RE.lastIndex=0;e.setAttribute(a,fix(v).trim())}EMO_RE.lastIndex=0})});
 root.querySelectorAll('input[value]').forEach(e=>{if(EMO_RE.test(e.value)){EMO_RE.lastIndex=0;e.value=fix(e.value).trim()}EMO_RE.lastIndex=0})}
const PURE_TOAST=/^\s*(S\.menu=null;)?\s*(draw\(\);)?\s*toast\(['"]Demo[ ]only[^'"]*['"]\)\s*;?\s*(S\.menu=null;\s*draw\(\))?;?\s*$/;
function sweep(root){if(!root||root.nodeType!=1)return;[root,...root.querySelectorAll('[onclick]')].forEach(e=>{const o=e.getAttribute&&e.getAttribute('onclick');if(!o)return;if(PURE_TOAST.test(o)){e.remove();window.__deadRemoved=(window.__deadRemoved||0)+1}})}
function initGuards(){deEmoji(document.body);sweep(document.body);new MutationObserver(ms=>ms.forEach(m=>m.addedNodes.forEach(n=>{deEmoji(n);sweep(n)}))).observe(document.body,{childList:true,subtree:true})}

