/* Legacy library structures (ITR, ITD, PHD, AUD, AUF, LIB) are snapshotted into saved state so folder/template edits persist. */
function libSnapshot(){return {ITR,ITD,PHD,AUD,AUF,LIB:Object.fromEntries(Object.entries(LIB).map(([k,v])=>[k,v[1]]))}}
function libRestore(L){if(!L)return;try{ITR.length=0;L.ITR.forEach(r=>ITR.push(r));Object.keys(L.ITD).forEach(k=>ITD[k]=L.ITD[k]);Object.keys(L.PHD).forEach(k=>PHD[k]=L.PHD[k]);Object.keys(L.AUD).forEach(k=>AUD[k]=L.AUD[k]);AUF.length=0;L.AUF.forEach(f=>AUF.push(f));Object.keys(L.LIB).forEach(k=>{if(LIB[k])LIB[k][1]=L.LIB[k]})}catch(e){console.error(e)}}
/* ---- one dispatcher for every remaining legacy toolbar control ---- */
