function libImport(){dlgW('Import to library (CSV)',`<p class="mu">One item per line: name, type/location, supplier. Items are added to the current library list.</p><textarea id="li1" rows="5">Algarve coastal walk,Activity (Tour),Algarve Guides\nPorto port lodge visit,Activity (Dining),Taylor's (demo)</textarea>`,'Import',()=>{const lines=val('li1').split('\n').map(r=>r.split(',').map(x=>x.trim())).filter(r=>r[0]);if(!lines.length)return err('Nothing to import.');const pg=S.pg;let n=0;if(LIB[pg]){const L=LIB[pg];L[1]=L[1]||[];lines.forEach(r=>{L[1].push({n:r[0],c:[r[1]||'Item',r[2]||'–',TD],f:0});n++})}else{lines.forEach(r=>{const a=A('custom',r[0],r[1]||'');a.supplier=r[2]||'';a.lib=1;X.lib.push(a);n++})}logA('','Library import: '+n+' items','info');cl();toast(n+' items imported');draw()},560)}
function photoUpload(){dlg('Upload photos',`<label>Images</label><input type="file" id="pu1" accept="image/*" multiple><p class="mu" style="font-size:12px">Stored in this browser (small images keep a preview).</p>`,'Upload',()=>{const fs=[...(document.getElementById('pu1').files||[])];if(!fs.length)return err('Choose at least one image.');const path=S.pfp.join('/'),e=PHD[path]||(PHD[path]=[[],0]);let left=fs.length;fs.forEach(f=>{const done=data=>{e[0].unshift([f.name,'',X.set.agency,TD]);X.docs.unshift({id:uid('d'),n:f.name,cat:'Images',kind:'image',size:(f.size/1024).toFixed(0)+' KB',trip:'',contact:'',bk:'',vis:'internal',at:TODAY(),data:data||''});if(--left==0){logA('',fs.length+' photo(s) uploaded','doc');cl();toast('Uploaded '+fs.length+' photo'+(fs.length>1?'s':''));draw()}};if(f.size<700000){const r=new FileReader();r.onload=()=>done(r.result);r.readAsDataURL(f)}else done('')})})}
/* ---- itinerary template (library) actions ---- */
const tplList=()=>{const t=S.tr_;if(!t)return null;const fp=t.fp!==undefined?t.fp:'';return fp?(ITD[fp]||null):ITR};
function tplPublish(){const t=S.tr_;t.pub=!t.pub;t.pubAt=t.pub?TODAY():'';logA('','Itinerary template '+(t.pub?'published to the agency library':'unpublished')+': '+t.n,'publish');toast(t.pub?'Template published to the agency library':'Template unpublished');draw()}
function tplMove(){const t=S.tr_,from=tplList();const folders=[['','My templates (top level)'],...Object.keys(ITD).filter(k=>!k.includes('.')).slice(0,80).map(k=>[k,k])];dlg('Move template',`<label>Destination folder</label>${sel('tm1',folders,t.fp||'')}`,'Move',()=>{const to=val('tm1');if(to==(t.fp||''))return err('Choose a different folder.');const row=from&&from.find(r=>r[0]==t.n);if(row)from.splice(from.indexOf(row),1);(to?(ITD[to]=ITD[to]||[]):ITR).unshift(row||[t.n,t.l,TD]);t.fp=to;t.f=to.split('/').pop()||'My templates';logA('','Template moved: '+t.n+' → '+(to||'My templates'),'info');cl();toast('Template moved');draw()})}
function tplDelete(){const t=S.tr_;dlg('Delete template',`<p>Delete <b>${esc(t.n)}</b> from the library? Trips already created from it are not affected.</p>`,'Delete',()=>{const L=tplList(),row=L&&L.find(r=>r[0]==t.n);if(row)L.splice(L.indexOf(row),1);logA('','Template deleted: '+t.n,'info');cl();S.tr_=null;toast('Template deleted');go('libit')})}
function tplItAct(op,i,j){const t=S.tr_,d=t.days[i];if(op=='dup'){const c=JSON.parse(JSON.stringify(d.a[j]));c[0]=c[0]+' (copy)';d.a.splice(+j+1,0,c);toast('Item duplicated')}
 if(op=='save'){const nm=j==='p'?d.p:d.a[j][0];const a=A(j==='p'?'cruise':'custom',nm,'Saved from itinerary template “'+t.n+'”');a.lib=1;X.lib.unshift(a);toast('Saved to Content hub › Activities')}
 if(op=='hide'){d.hid=d.hid||{};d.hid[j]=!d.hid[j];toast(d.hid[j]?'Hidden from travelers':'Visible to travelers')}
 if(op=='delport'){d.p='';if(!(d.a||[]).length)t.days.splice(i,1);toast('Port removed')}
 logA('','Template item updated ('+op+'): '+t.n,'info');draw()}
function tplOpt(x){const t=S.tr_;switch(x){case 'Edit itinerary':if(t.days&&t.days.length)tact(0,t.days[0].p?'p':0);return;case 'Approve itinerary':t.appr=1;toast('Template marked approved');break;case 'Download PDF':tplPrev();setTimeout(()=>window.print(),80);return;case 'Reject / archive itinerary':t.arch=!t.arch;toast(t.arch?'Template archived':'Template restored');break;case 'Duplicate itinerary':case 'Save itinerary as template':{const L=tplList()||ITR;L.unshift([t.n+(x.startsWith('Dup')?' (copy)':' (template)'),t.l,TD]);toast(x.startsWith('Dup')?'Duplicated in this folder':'Saved as a new template');break}case 'Delete itinerary':return tplDelete()}logA('','Template action: '+x+' — '+t.n,'info');draw()}
function pkgDlg(){const t=S.tr_,a=S.ta;if(!t||!a)return;const k=a.i+':'+a.j,b=bpg(k);dlg('Add to a package',`<p class="mu">Group this item with others so they price and display as one package.</p><label>Package name</label><input id="pk1" list="pkl" value="${esc(b.pkg||'')}"><datalist id="pkl">${[...new Set(Object.values(t.bp||{}).map(x=>x.pkg).filter(Boolean))].map(x=>`<option>${esc(x)}</option>`).join('')}</datalist>`,'Save',()=>{b.pkg=val('pk1');cl();toast(b.pkg?'Added to package “'+b.pkg+'”':'Removed from package');draw()})}
/* ---- legacy (imported) automation editor → LTI builder for AI, status and template actions ---- */
function abFromLegacy(kind){const t=aut();S.menu=null;if(!guard('auto.edit'))return;const d=blankAuto();d.name=(t?t.name+' — ':'')+(kind=='ai'?'AI agent step':'Update trip status');const evMap={trip_status_changes:'trip_status_changed',trip_start_date:'trip_starts',trip_end_date:'trip_ends',trip_created_date:'trip_created',trip_client_approves_trip:'client_approves',trip_client_requests_trip_edits:'client_requests_edits',trip_client_authorizes_payments:'client_authorizes_payment'};if(t&&evMap[t.ev])d.trig=evMap[t.ev];d.acts=[kind=='ai'?{type:'ai',kind:'draft_email'}:{type:'status',to:'Booked'}];S._ad=d;X.ui.autoId='';go('autobuild');toast('Opened in the LTI automation builder')}
function auTaskTpl(){S.menu=null;dlg('Add task from template',`<label>Task template</label>${sel('at1',X.taskTpl.map(t=>[t.id,t.n]),'')}`,'Add task',()=>{const tt=X.taskTpl.find(x=>x.id==val('at1'));aut().acts.push(Object.assign(auTask(),{title:tt.n,due:Math.abs(tt.days||1)}));aufl();cl();draw()})}
function auRootDup(t){AUD['My templates']=AUD['My templates']||[];if(!AUF.includes('My templates'))AUF.push('My templates');const r=t.row.slice();r[0]=t.name+' (copy)';r[5]='Inactive';r[6]=TD;AUD['My templates'].unshift(r);toast('Copied to the “My templates” folder');S.afp=['My templates'];go('libau')}
function auRootDel(t){dlg('Delete automation',`<p>Delete <b>${esc(t.name)}</b>?</p>`,'Delete',()=>{X.auRootGone=1;cl();toast('Automation deleted');S.afp=[];go('libau')})}
/* ---- task/workflow library editor ---- */
function lwEdit(k,id){const r=lwF(k,id);if(k=='libwf'){let w=X.wfs.find(x=>x.n==r.n);if(!w){w={id:uid('wf'),n:r.n,scope:'trip',cat:'Library',desc:'Created from the workflow library',steps:[],active:0,auto:{on:0,trig:'trip_created',cond:{logic:'AND',rules:[]}},hist:[],created:TODAY()};X.wfs.push(w)}X.ui.wfId=w.id;go('workflows');return}
 r.tasks=r.tasks||[];dlgW('Edit task template',`<label>Name</label><input id="lw1" value="${esc(r.n)}"><label>Tasks (one per line; optional “| days”)</label><textarea id="lw2" rows="6" placeholder="Send welcome packet | 1">${esc(r.tasks.join('\n'))}</textarea>`,'Save',()=>{if(!val('lw1'))return err('Enter a name.');r.n=val('lw1');r.tasks=val('lw2').split('\n').map(x=>x.trim()).filter(Boolean);r.c=[r.tasks.length+' task'+(r.tasks.length==1?'':'s')];r.d=TD;r.tasks.forEach(line=>{const [n,dd]=line.split('|').map(x=>x.trim());if(!X.taskTpl.some(t=>t.n==n))X.taskTpl.push({id:uid('tt'),n,days:+dd||1,pri:'Medium'})});cl();toast('Task template saved');draw()},560)}
/* ---- overridden legacy pages ---- */
Pg.cominv=()=>{X.cominv=X.cominv||[];const exp=X.comm.filter(c=>c.st=='Expected'&&(X.bookings.find(b=>b.ref==c.bk)||{}).date<addD(TODAY(),30));return hd('Commission invoices',`<button class="btn" onclick="ciNew()" ${dis('fin.reconcile')}>Invoice a supplier</button>`,'Bill suppliers for commission they owe the agency')+`<div class="g g4" style="margin-bottom:14px">${kpi('Invoices sent',X.cominv.length)}${kpi('Amount invoiced',mny(sum(X.cominv,i=>i.amt)))}${kpi('Paid by suppliers',mny(sum(X.cominv.filter(i=>i.st=='Paid'),i=>i.amt)))}${kpi('Eligible to invoice',exp.length,'expected commission, travel within 30 days or past')}</div>`+cd('Supplier commission invoices',X.cominv.length?tbl(['Invoice','Supplier','Bookings','Date','Amount','Status',''],X.cominv.map(i=>[i.id,esc(i.sup),i.bks.join(', '),fd(i.at),mny(i.amt),pill(i.st,i.st=='Paid'?'Active':'Pending'),i.st=='Paid'?'':`<button class="btn o s" onclick="ciPaid('${i.id}')" ${dis('fin.reconcile')}>Mark paid</button>`])):emp('file','No commission invoices yet','Invoice a supplier for expected commission.'),'',1)};
function ciNew(){if(!guard('fin.reconcile'))return;const sups=[...new Set(X.comm.filter(c=>c.st=='Expected').map(c=>c.supplier))];if(!sups.length)return toast('No expected commission to invoice');dlg('Invoice a supplier',`<label>Supplier</label>${sel('ci1',sups,sups[0],'onchange="ciPv()"')}<div id="cipv" style="margin-top:10px"></div>`,'Create invoice',()=>{const s=val('ci1'),l=X.comm.filter(c=>c.st=='Expected'&&c.supplier==s);const id='CI-'+String(101+(X.cominv||[]).length);X.cominv.unshift({id,sup:s,bks:l.map(c=>c.bk),amt:sum(l,c=>c.exp),at:TODAY(),st:'Sent'});l.forEach(c=>c.inv=id);logA('',`Commission invoice ${id} to ${s}: ${mny(sum(l,c=>c.exp))}`,'finance');cl();draw()});ciPv()}
function ciPv(){const s=val('ci1'),l=X.comm.filter(c=>c.st=='Expected'&&c.supplier==s);const e=$('#cipv');if(e)e.innerHTML=l.map(c=>`<div class="row sp ts" style="font-size:13px"><span>${c.bk}</span><b>${mny(c.exp)}</b></div>`).join('')+`<div class="row sp ts"><b>Total</b><b>${mny(sum(l,c=>c.exp))}</b></div>`}
function ciPaid(id){const i=X.cominv.find(x=>x.id==id);i.st='Paid';i.bks.forEach(r=>{const c=X.comm.find(x=>x.bk==r);if(c&&c.st=='Expected'){c.rec=c.exp;c.st='Matched'}});logA('',`Commission invoice ${id} paid by ${i.sup}`,'finance');draw()}
const INTS=[['Email (Gmail / Outlook)','Sync inbox and send from company addresses'],['Calendar (Google / Microsoft)','Two-way appointment sync'],['Payments processor','Hosted card authorization and capture'],['Accounting (QuickBooks / Xero)','Export invoices and commission'],['Business telephony (Twilio Voice / SIP)','Softphone calling, routing, voicemail, recordings'],['Zapier / n8n','Webhooks for custom workflows'],['Tern data migration','Import contacts, trips and templates']];
Pg.integ=()=>{X.intReq=X.intReq||{};return hd('Integrations',``,'Connections are configured in the implementation phase; request and track setup here')+INTS.map(x=>{const r=X.intReq[x[0]];return `<div class="iv"><div class="lgo">${ic('plug')}</div><div><b>${x[0]}</b><p>${x[1]}</p></div>${r?`<span class="tag">Setup requested ${fd(r.at)}</span>`:`<button class="btn o" onclick="intReq('${x[0]}')" ${dis('settings.edit')}>Request setup</button>`}</div>`}).join('')}
function intReq(n){if(!guard('settings.edit'))return;dlg('Request integration setup',`<p><b>${esc(n)}</b></p><label>Notes for the implementation team</label><textarea id="ir1" rows="3"></textarea>`,'Submit request',()=>{X.intReq=X.intReq||{};X.intReq[n]={at:TODAY(),notes:val('ir1')};addTask({t:'Integration setup request: '+n,due:addD(TODAY(),7),pri:'Medium',asg:'Maya Reyes',src:'Integrations',list:'Operations',desc:val('ir1')});cl();toast('Request logged as a task');draw()})}
Pg.terms=()=>{X.terms=X.terms||{txt:'1. Deposits are non-refundable unless stated by the supplier.\n2. Final payment is due 45 days before departure.\n3. Travel insurance is strongly recommended.\n4. Itineraries may change due to supplier schedules.',pub:0,at:''};const T2=X.terms,ro=can('settings.edit')?'':'disabled';return hd('Terms & conditions',`<button class="btn o" onclick="dlgW('Terms preview (client view)','<div class=&quot;emv&quot; style=&quot;white-space:pre-wrap&quot;>'+esc(X.terms.txt)+'</div>',null,null,620)">${ic('eye',14)} Preview</button><button class="btn" onclick="X.terms.pub=X.terms.pub?0:1;X.terms.at=TODAY();logA('','Terms '+(X.terms.pub?'published':'unpublished'),'publish');draw()" ${dis('settings.edit')}>${T2.pub?'Unpublish':'Publish'}</button>`,`${T2.pub?pill('Published')+' '+fd(T2.at):'<span class="tag">Unpublished</span>'} · shown to travelers on the client portal when published`)+cd('Agency terms',`<textarea rows="12" aria-label="Terms text" onchange="X.terms.txt=this.value;logA('','Terms edited','info')" ${ro}>${esc(T2.txt)}</textarea>`)};
const HELP=[['Creating a trip','Trips › New trip. Choose a client, dates and type. The New Client Inquiry workflow runs automatically.'],['Building an itinerary','Itinerary editor: add days, drag activities between days, set internal and client notes, then Publish.'],['Client portal permissions','Primary travelers approve and authorize payments; Full access can view payments and request changes; Limited sees the itinerary only.'],['Automations and the demo clock','Automations run when you move the demo clock or press Process due runs. Use Test to simulate a rule.'],['Workflows','Bundles of tasks and automations. Apply manually, in bulk, or automatically when criteria match.'],['Payments and authorizations','Request authorization, travelers authorize with a masked demo method, then record the payment.'],['Commission reconciliation','Import a supplier statement, accept suggested matches, reconcile, then build payouts.'],['Making and receiving calls','Open the softphone from the phone icon. After each call, save a call summary; dispositions can trigger automations.'],['Voicemail and recordings','Calls › Voicemail and Recordings. Playback is simulated; transcripts are demo text.'],['Roles','Profile menu › switch role to preview what each staff member sees.'],['Resetting the demo','Settings › Demo data › Reset demo data restores the original sample records.']];
const _helpPg=Pg.help;Pg.help=()=>{const q=(X.ui.hq||'').toLowerCase(),l=HELP.filter(h=>(h[0]+h[1]).toLowerCase().includes(q));return hd('Help center',`<button class="btn o" onclick="tourStart()">Take the tour</button><button class="btn" onclick="go('hsup')">Contact support</button>`)+`<div class="row" style="margin-bottom:12px">${searchBox('hq',X.ui.hq,"X.ui.hq=this.value;clearTimeout(window._hq);window._hq=setTimeout(()=>{draw();const e=$('#hq');e.focus();e.setSelectionRange(e.value.length,e.value.length)},200)",'Search help articles')}</div>`+cd(`Articles (${l.length})`,l.map(h=>`<details class="hlp"><summary>${esc(h[0])}</summary><p>${esc(h[1])}</p></details>`).join('')||'<p class="mu">No articles match.</p>')+JOURNEYS.map(j=>cd(j[0],`<ol style="margin:0;padding-left:20px">${j[1].map(s=>`<li style="margin:4px 0">${esc(s)}</li>`).join('')}</ol>`)).join('')};
Pg.hsup=()=>hd('Contact support',``,'Internal IT and operations support for LTI staff')+cd('New request',`<div class="fm" style="max-width:640px"><label>Category</label>${sel('hs1',['Platform question','Bug report','Access / permissions','Integration request'],'Platform question')}<label>Describe the issue</label><textarea id="hs2" rows="5"></textarea><button class="btn g1" style="margin-top:10px" onclick="hsupSend()">Submit request</button></div>`)+cd('Your requests',S.tasks.filter(k=>k.src=='Support request').map(k=>`<div class="ts"><span style="flex:1">${esc(k.t)}<div class="mu" style="font-size:12px">${fd(k.due)} · ${k.x?'Resolved':'Open'}</div></span></div>`).join('')||'<p class="mu">No requests yet.</p>');
function hsupSend(){const d=val('hs2');if(!d){toast('Describe the issue first');return}addTask({t:val('hs1')+': '+d.slice(0,60),due:addD(TODAY(),1),pri:'Medium',asg:'Maya Reyes',src:'Support request',list:'Operations',desc:d});notify('Support request logged: '+val('hs1'),'','info');toast('Request submitted — assigned to the administrator');draw()}
function pwReset(){const e=prompt?null:null;addTask({t:'Password reset requested from sign-in screen',due:TODAY(),pri:'High',asg:'Maya Reyes',src:'Support request',list:'Operations'});const n=document.getElementById('pwmsg');if(n)n.textContent='Reset request sent to your administrator.'}
function tplPhoto(){dlg('Template cover photo','<input type="file" id="tp1" accept="image/*">','Use photo',()=>{const f=(document.getElementById('tp1').files||[])[0];if(!f)return err('Choose an image.');if(f.size>700000)return err('Image too large for local storage (max ~700 KB).');const r=new FileReader();r.onload=()=>{S.tr_.img=r.result;cl();toast('Cover photo updated');draw()};r.readAsDataURL(f)})}
Pg.libd=()=>Pg.docs();Pg.libt=()=>Pg.libit();Pg.rpview=()=>Pg.reporting2();Pg.rpc=Pg.rpview;
/* ---- itinerary template editor: add items, add from library, media ---- */
function tplProto(name){const t=S.tr_,p=(t.days||[]).flatMap(d=>d.a||[])[0];return p?p.map((v,i)=>i==0?name:(typeof v=='number'?0:Array.isArray(v)?[]:'')):[name]}
function tplAddItem(i,type){const t=S.tr_;if(!t.days||!t.days.length)t.days=[{p:'',a:[]}];const d=t.days[Math.min(i,t.days.length-1)];d.a=d.a||[];if(type=='Port info'){dlg('Port of call','<label>Port name</label><input id="pp1">','Add port',()=>{if(!val('pp1'))return err('Enter a port.');d.p=val('pp1');cl();draw()});return}
 dlg('Add '+type.toLowerCase(),`<label>Name</label><input id="ta1" value="New ${esc(type.toLowerCase())}">`,'Add',()=>{const n=val('ta1');if(!n)return err('Enter a name.');d.a.push(tplProto(n));logA('','Template item added: '+n+' ('+type+')','info');cl();toast(type+' added to Day '+(t.days.indexOf(d)+1));draw()})}
function tplFromLib(i,src){const t=S.tr_,d=t.days[i];const pick={'Hotel library':'hotel','Cruise template':'cruise','Tour library':'tour','Transfer quote':'transfer','Activity template':''}[src];
 if(src=='Import from ALGV'){dlg('Import supplier itinerary lines','<p class="mu">Paste one line per item (e.g. from a supplier confirmation).</p><textarea id="ag1" rows="5"></textarea>','Import',()=>{const L=val('ag1').split('\n').map(x=>x.trim()).filter(Boolean);if(!L.length)return err('Paste at least one line.');L.forEach(n=>d.a.push(tplProto(n)));cl();toast(L.length+' items imported to Day '+(i+1));draw()});return}
 const items=src=='Itinerary template'?ITR.filter(r=>r[1]!==null).map(r=>r[0]):X.lib.filter(a=>!pick||a.type==pick).map(a=>a.title);
 dlg(src,items.length?`<label>Choose</label>${sel('tl1',items,items[0])}`:'<p class="mu">Nothing in this library yet — add items in the Content hub.</p>',items.length?'Add to day':null,()=>{d.a.push(tplProto(val('tl1')));cl();toast('Added to Day '+(i+1));draw()})}
function tactMedia(mode){const a=S.ta,t=S.tr_,key=a?a.i+':'+a.j:'x';t.media=t.media||{};const save=src=>{(t.media[key]=t.media[key]||[]).push(src);X.docs.unshift({id:uid('d'),n:(t.n+' — media').slice(0,60),cat:'Images',kind:'image',size:'',trip:'',contact:'',bk:'',vis:'client',at:TODAY(),data:src.startsWith('data:')?src:''});cl();toast('Photo added');draw()};
 if(mode=='Import from URL'){dlg('Import photo from URL','<label>Image URL</label><input id="mu1" placeholder="https://"><p class="mu" style="font-size:12px">Saved as a reference; published pages only display images stored inside the app.</p>','Add',()=>{if(!/^https?:\/\//.test(val('mu1')))return err('Enter a full http(s) URL.');save(val('mu1'))});return}
 if(mode=='Add from library'){const imgs=X.docs.filter(d=>d.kind=='image'&&d.data);dlg('Add from library',imgs.length?sel('ml1',imgs.map(d=>[d.id,d.n]),''):'<p class="mu">No stored images yet — upload one first.</p>',imgs.length?'Add':null,()=>save(X.docs.find(d=>d.id==val('ml1')).data));return}
 dlg('Add photo','<input type="file" id="mf1" accept="image/*">','Add',()=>{const f=(document.getElementById('mf1').files||[])[0];if(!f)return err('Choose an image.');if(f.size>700000)return err('Image too large (max ~700 KB).');const r=new FileReader();r.onload=()=>save(r.result);r.readAsDataURL(f)})}
/* ---- historical imports (bookings, suppliers) ---- */
function bkImportCsv(){if(!guard('fin.record'))return;dlgW('Import historical bookings (CSV)','<p class="mu">Columns: client, supplier, type, amount, travel date (YYYY-MM-DD), confirmation.</p><textarea id="bi1" rows="5">Helen Ruiz,AmaWaterways,Cruise,4200,2025-12-12,AMA-55102\nTomás Ibarra,Lisbon Private Tours,Tour,650,2025-06-04,LPT-2211</textarea>','Import',()=>{const L=val('bi1').split('\n').map(r=>r.split(',').map(x=>x.trim())).filter(r=>r[0]&&+r[3]>0);if(!L.length)return err('No valid rows (amount must be a number).');L.forEach(r=>{const ref=nextBkRef(),rate=(X.supx[r[1]]||{}).rate??10;X.bookings.push({ref,tripId:'',client:r[0],supplier:r[1],type:r[2]||'Other',amt:+r[3],st:'Confirmed',date:r[4]||TODAY(),conf:r[5]||'',comm:Math.round(+r[3]*rate)/100,rate,agent:X.me,trv:[],docs:[],hist:[{at:TODAY(),txt:'Imported from CSV'}],cxl:0})});logA('',L.length+' historical bookings imported','finance');cl();toast(L.length+' bookings imported');draw()},620)}
function supImportCsv(){if(!guard('fin.record'))return;dlgW('Import suppliers (CSV)','<p class="mu">Columns: name, category, commission %.</p><textarea id="si9" rows="4">Six Senses Douro Valley,Lodging,10\nAzores Whale Watch Co.,Activities,12</textarea>','Import',()=>{let n=0;val('si9').split('\n').map(r=>r.split(',').map(x=>x.trim())).filter(r=>r[0]).forEach(r=>{if(S.sup.some(s=>s[0].toLowerCase()==r[0].toLowerCase()))return;S.sup.push([r[0],0,uid('S'),SCAT.includes(r[1])?r[1]:'Other','',1,'']);X.supx[r[0]]={contact:'',email:'',phone:'',rate:+r[2]||10,notes:'',content:[]};n++});if(!n)return err('No new suppliers found.');logA('',n+' suppliers imported','finance');cl();toast(n+' suppliers imported');draw()},560)}
async function aiGoLegacy(){const e=document.getElementById('aiq'),q=e?e.value.trim():'';go('ai');if(q){setTimeout(()=>{const i=document.getElementById('aiq2');if(i){i.value=q;aiAsk()}},30)}}

/* ===================== Navigation, top bar, persistence & startup ===================== */
function topBar(){const s=sec(S.pg),nu=unread();
 if(X.role=='Traveler')return `<div class="lg"><img src="${X.set.logo||LOGO}" alt="Luxury Travel Institute logo"><span>Traveler portal</span></div><span class="demo-tag" style="margin-left:auto">Demo · Traveler role</span><button class="btn o s" style="margin-left:8px" onclick="setRole('Owner')">Exit traveler view</button>`;
 return `<button class="ib hb" aria-label="Open menu" onclick="S.dr=1;draw()">${ic('menu',18)}</button><div class="lg"><img src="${X.set.logo||LOGO}" alt="Luxury Travel Institute logo"></div><nav class="tn" aria-label="Main">${navFor().map(n=>n[0]=='he'?`<span class="rel"><a class="${n[0]==s[0]?'on':''}" onclick="mn('h')">Help ${ic('chev',12)}</a>${S.menu=='h'?`<div class="dd" style="left:0;right:auto;top:52px"><a onclick="go('help')">Guided journeys</a><a onclick="go('hsup')">Contact support</a><a onclick="tourStart()">Take the tour</a></div>`:''}</span>`:`<a class="${n[0]==s[0]?'on':''}" onclick="go('${n[3][0][1][0][0]}')">${n[1]}</a>`).join('')}</nav>
 <div class="sr"><span>${ic('search')}</span><input aria-label="Search contacts" placeholder="Search contacts" onkeydown="if(event.key=='Enter'){S.q=this.value;go('contacts')}"></div>
 <button class="dchip ml" onclick="go('automations')" title="Demo clock — click to manage">${ic('cal',13)} ${fds(TODAY())}${pendingNow()?` <b class="dot2"></b>`:''}</button>
 ${can('calls.use')?`<button class="ib" aria-label="Softphone" onclick="spOpen()">${ic('phone',17)}${X.calls.filter(c=>c.st=='Missed'&&c.date>=addD(TODAY(),-1)).length?'<b></b>':''}</button>`:''}<button class="ib" aria-label="Calendar" onclick="go('calendar')">${ic('cal',17)}</button><button class="ib" aria-label="My tasks" onclick="go('tasks')">${ic('list',17)}</button>
 <div class="rel"><button class="ib" aria-label="Notifications${nu?', '+nu+' unread':''}" onclick="mn('b')">${ic('bell',17)}${nu?`<span class="nbadge">${nu>9?'9+':nu}</span>`:''}</button>${S.menu=='b'?`<div class="dd" style="width:320px"><div class="row sp" style="padding:4px 10px"><span class="mu">Notifications</span><a class="lk" style="font-size:12px;padding:0;display:inline" onclick="X.notifs.forEach(n=>n.read=1);S.menu=null;draw()">Mark all read</a></div>${X.notifs.slice(0,7).map(n=>`<a onclick="X.notifs.find(x=>x.id=='${n.id}').read=1;S.menu=null;${n.ref?`openRef('${n.ref}')`:'draw()'}" style="font-size:13px">${n.read?'':'<b style="color:var(--gd)">● </b>'}${esc(n.txt)}<div class="mu" style="font-size:11px">${esc(n.at)}</div></a>`).join('')||'<div class="mu">No notifications yet</div>'}<a onclick="go('notifications')" style="font-weight:600">View all</a></div>`:''}</div>
 <div class="rel"><button class="pf" aria-label="Profile and demo role" onclick="mn('p')">${ini(X.set.profile.name)}</button>${S.menu=='p'?`<div class="dd"><div class="mu">${esc(X.set.profile.name)} · ${esc(roleLabel(X.role))} (demo)</div><div class="mu" style="padding-top:8px">Switch demo role</div>${ROLES.map(r=>`<a onclick="setRole('${r}')">${r==X.role?'● ':''}${roleLabel(r)}</a>`).join('')}<hr class="hr" style="margin:6px 0"><a onclick="go('settings')">Settings</a><a onclick="go('roles')">Staff & permissions</a><a onclick="go('callset')">Call settings</a><a onclick="S.tab.st='Demo data';go('settings')">Demo data & reset</a><a onclick="si()">Sign out</a></div>`:''}</div>`}
function initNav(){
 const B=N.find(n=>n[0]=='bo');B[3][0][1]=[['dashboard','Dashboard'],['suppliers','Suppliers'],['bookings','Bookings'],['payments','Payments'],['commission','Commission'],['cominv','Commission invoices']];B[3][2][1]=[['settings','Settings'],['agency','Agency details'],['tags','Tags'],['roles','Staff & permissions'],['controls','Agency controls'],['integ','Integrations'],['terms','Terms & conditions']];
 N.find(n=>n[0]=='tr')[3]=[['Trips',[['trips','My Trips'],['groups','Group trips'],['itinerary','Itinerary editor'],['portal','Client portal']]]];
 N.find(n=>n[0]=='ta')[3]=[['Planning',[['tasks','Tasks'],['calendar','Calendar'],['scheduling','Scheduling']]]];
 N.find(n=>n[0]=='li')[3][0][1].unshift(['content','Content hub']);
 const li=N.findIndex(n=>n[0]=='li');N.splice(li+1,0,['au','Automate','bolt',[['Automate',[['automations','Automations'],['workflows','Workflows'],['ai','AI workspace']]]]]);
 N.find(n=>n[0]=='em')[3]=[['Mail',[['emails','Inbox'],['smart','Smart inbox'],['outbox','Sent & scheduled'],['emt','Templates']]]];
 N.find(n=>n[0]=='co')[3]=[['Contacts',[['contacts','Contacts'],['trav','Travelers'],['forms','Forms & intake'],['docs','Documents']]]];
 N.find(n=>n[0]=='rp')[3][0][1].unshift(['reporting2','Analytics']);
 const coi=N.findIndex(n=>n[0]=='co');N.splice(coi+1,0,['ca','Calls','phone',[['Calls',[['calls','Dialer'],['callhist','Call history'],['voicemail','Voicemail'],['recordings','Recordings'],['callan','Call analytics'],['callset','Call settings']]]]]);
 Object.assign(ALIAS,{team:'roles',preview:'portal',autobuild:'automations',notifications:'dashboard',comm:'commission'});
 Object.assign(ICN,{payments:'card',settings:'sliders',roles:'users',groups:'users',portal:'eye',scheduling:'cal',content:'book',automations:'bolt',workflows:'globe',ai:'star',smart:'inbox',outbox:'mail',emt:'mail',forms:'copy',docs:'folder',reporting2:'chart',trav:'user'});
 Pg.preview=Pg.portal;Pg.team=Pg.roles;Pg.invoices=()=>{S.tab.pay='Invoices';return Pg.payments()};
}
let _saveT=null;
function initDraw(){const _draw=draw;draw=function(){if(X.role=='Traveler'&&S.pg!='portal')S.pg='portal';if(!Pg[S.pg])S.pg='dashboard';if(!secAllowed(sec(S.pg)[0])){S.pg='dashboard'}_draw();try{applyTV();applyLibSearch();applyPaging()}catch(e){console.error(e)};
  try{$('#top').innerHTML=topBar();const s=sec(S.pg),items=s[3].reduce((n,g)=>n+g[1].length,0);if(X.role=='Traveler'){$('#sb').style.display='none'}else if(S.pg!='trip'&&S.pg!='tpl'&&S.pg!='tact'&&items>1){$('#sb').style.display=''}
   const f=$('#m').lastElementChild;if(f&&f.tagName=='P'&&/Demo preview/.test(f.textContent))f.textContent='Demo prototype · sample data saved in this browser only · no emails, payments or AI calls leave this page.';}catch(e){console.error(e)}
  clearTimeout(_saveT);_saveT=setTimeout(persist,120)}}
(function start(){if(restore()){X=S.X}else{seed()}X.phone.call=null;X.phone.open=0;initNav();initDraw();applyBrand();spMount();initGuards();
 const h=location.hash.slice(1);if(Pg[h])S.pg=h;if(!S.cur||!tripById(S.cur))S.cur='t1';draw();
 window.__LTI_READY=1})();

